import { useGame } from '../GameContext';
import { motion } from 'framer-motion';
import { MOCK_STORY } from '@/data/story';
import {
  Activity,
  Users,
  Heart,
  AlertTriangle,
  ChevronRight,
  FileText,
  ClipboardList,
  ShieldAlert,
} from 'lucide-react';
import SceneChrome from '../components/SceneChrome';
import OasTopNav from '../components/OasTopNav';

export default function OasDashboardScene() {
  const { goToScene, state, resetGame, hasCompletedRun } = useGame();
  const { oas, characters } = MOCK_STORY;

  const statIcons = [Activity, Users, Heart];

  const handleStatClick = (statKey: string) => {
    if (statKey === 'allocation') {
      goToScene('oasAllocation');
    } else if (statKey === 'completedFollowup' || statKey === 'followup' || statKey === 'pending') {
      goToScene('oasFollowup');
    } else if (statKey === 'alert') {
      goToScene('oasAlerts');
    } else if (statKey === 'waiting') {
      goToScene('oasArchives');
    }
  };

  const handleArchiveClick = (archiveId: string) => {
    if (archiveId === 'shenchi') {
      goToScene('shenchiPuzzle');
    } else if (archiveId === 'shenbo') {
      goToScene('shenboPuzzle');
    }
  };

  const handleViewAllArchives = () => {
    goToScene('oasArchives');
  };

  return (
    <div className="min-h-screen bg-[#f0f2f5]">
      <SceneChrome variant="system" showBack={false} />

      <OasTopNav activeTab="dashboard" />

      {/* 主内容区 */}
      <div className="max-w-6xl mx-auto px-4 py-5">
        {/* 面包屑 */}
        <div className="text-xs text-gray-500 mb-4">
          当前位置：<span className="text-gray-700">工作台</span>
        </div>

        {/* 欢迎区 */}
        <motion.div
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.3 }}
          className="bg-white border border-gray-200 p-4 mb-4"
        >
          <div className="flex items-center justify-between flex-wrap gap-2">
            <div>
               <h1 className="text-base font-medium text-gray-800">
                 {oas.dashboardTitle}
               </h1>
               <p className="text-xs text-gray-500 mt-1">
                 欢迎回来，{characters.player.name}（{characters.player.role}）
               </p>
               {hasCompletedRun && (
                 <button
                   onClick={() => goToScene('myRecord')}
                   className="text-[10px] text-gray-400 hover:text-[#1e5b9d] mt-1 underline underline-offset-2"
                 >
                   查看员工健康档案
                 </button>
               )}
             </div>
            <div className="text-xs text-gray-500">
              {new Date().toLocaleDateString('zh-CN', {
                year: 'numeric',
                month: 'long',
                day: 'numeric',
                weekday: 'long',
              })}
            </div>
          </div>
        </motion.div>

        {/* 数据概览 */}
        <motion.div
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.3, delay: 0.1 }}
          className="grid grid-cols-3 md:grid-cols-6 gap-3 mb-4"
        >
          {oas.stats.map((stat, i) => {
            const Icon = statIcons[i % statIcons.length];
            return (
              <div
                key={i}
                onClick={() => handleStatClick(stat.statKey)}
                className="bg-white border border-gray-200 p-3 text-center cursor-pointer hover:border-[#1e5b9d] hover:shadow-sm transition-colors"
              >
                <div className="w-7 h-7 mx-auto mb-2 bg-blue-50 flex items-center justify-center">
                  <Icon className="w-3.5 h-3.5 text-[#1e5b9d]" />
                </div>
                <p className="text-xs text-gray-500 mb-1 truncate">{stat.label}</p>
                <p className="text-lg font-bold text-gray-800 tabular-nums">
                  {stat.value}
                </p>
              </div>
            );
          })}
        </motion.div>

        {/* 异常档案 */}
        <motion.div
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.3, delay: 0.2 }}
          className="bg-white border border-gray-200 mb-4"
        >
          <div className="border-b border-gray-200 px-4 py-3 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <AlertTriangle className="w-4 h-4 text-red-600" />
              <h2 className="text-sm font-medium text-gray-800">异常档案</h2>
              <span className="text-xs bg-red-100 text-red-700 px-1.5 py-0.5">
                {oas.archives.length} 份待处理
              </span>
            </div>
            <button
              onClick={handleViewAllArchives}
              className="text-xs text-[#1e5b9d] hover:underline"
            >
              查看全部 →
            </button>
          </div>

          <div className="divide-y divide-gray-100">
              {oas.archives.map((archive, i) => (
                <motion.div
                  key={archive.id}
                  initial={{ y: 8 }}
                  animate={{ y: 0 }}
                  transition={{ delay: 0.3 + i * 0.1, duration: 0.4 }}
                  onClick={() => handleArchiveClick(archive.id)}
                  className="p-4 hover:bg-red-50/50 cursor-pointer transition-colors border-l-2 border-l-red-500"
              >
                <div className="flex items-start gap-3">
                  <div className="w-9 h-9 bg-red-50 flex items-center justify-center flex-shrink-0 mt-0.5">
                    {archive.id === 'shenchi' ? (
                      <Heart className="w-4 h-4 text-red-600" />
                    ) : (
                      <ClipboardList className="w-4 h-4 text-red-600" />
                    )}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <h3 className="text-sm font-medium text-gray-800">
                        {archive.name}
                      </h3>
                      <span className="text-xs bg-red-500 text-white px-1.5 py-0.5">
                        {archive.status}
                      </span>
                      <span className="text-xs text-gray-400 font-mono">
                        {archive.archiveNo}
                      </span>
                    </div>
                    <div className="text-xs text-gray-500 mt-1 flex items-center gap-2 flex-wrap">
                      <span>{archive.age}岁</span>
                      <span className="text-gray-300">|</span>
                      <span>{archive.city}</span>
                      <span className="text-gray-300">|</span>
                      <span>{archive.organType}</span>
                    </div>
                    <p className="text-xs text-gray-600 mt-2 leading-relaxed">
                      {archive.description}
                    </p>
                  </div>
                  <span className="text-xs text-[#1e5b9d] flex-shrink-0 mt-1">
                    查看详情 →
                  </span>
                </div>
              </motion.div>
            ))}
          </div>
        </motion.div>

        {/* 异常访问预警 */}
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.4, delay: 0.4 }}
          className="mb-4 cursor-pointer"
          onClick={() => goToScene('oasAlerts')}
        >
          <div className="flex items-center gap-2 mb-3">
            <ShieldAlert className="w-5 h-5 text-orange-500" />
            <h2 className="text-base font-semibold text-slate-800">异常访问预警</h2>
            <span className="text-xs bg-orange-500/15 text-orange-600 border border-orange-200 px-2 py-0.5">
              高危 · {oas.alertEvents.length} 条
            </span>
          </div>

          <div className="border border-orange-200 bg-orange-50/60 rounded-lg overflow-hidden hover:shadow-sm transition-shadow">
            <div className="px-4 py-3 bg-orange-100/50 border-b border-orange-200 flex items-center justify-between flex-wrap gap-2">
              <div className="flex items-center gap-2">
                <FileText className="w-4 h-4 text-orange-600" />
                <span className="text-sm font-medium text-orange-800">
                  {oas.alertEvents[0]?.title}
                </span>
              </div>
              <span className="text-xs text-orange-500">
                {oas.alertEvents[0]?.time}
              </span>
            </div>
            <div className="p-4">
              <p className="text-sm text-orange-700 line-clamp-2">
                {oas.alertEvents[0]?.detail}
              </p>
              <div className="mt-3 flex items-center justify-between">
                <span className="text-xs text-orange-600">
                  已自动拦截 1,247 次非法请求
                </span>
                <span className="text-xs text-[#1e5b9d] flex items-center gap-1">
                  查看全部 <ChevronRight className="w-3 h-3" />
                </span>
              </div>
            </div>
          </div>
        </motion.div>

        {/* 近期随访表格 */}
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.3, delay: 0.5 }}
          className="bg-white border border-gray-200"
        >
          <div className="border-b border-gray-200 px-4 py-3 flex items-center justify-between">
            <h2 className="text-sm font-medium text-gray-800">近期随访记录</h2>
            <button
              onClick={() => goToScene('oasFollowup')}
              className="text-xs text-[#1e5b9d] hover:underline"
            >
              全部随访 →
            </button>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-200">
                  <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-500">
                    档案编号
                  </th>
                  <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-500">
                    姓名
                  </th>
                  <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-500">
                    类型
                  </th>
                  <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-500">
                    状态
                  </th>
                  <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-500">
                    最近随访
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                <tr className="hover:bg-gray-50">
                  <td className="px-4 py-2.5 text-xs text-gray-600 font-mono">
                    OAS-2026-00187
                  </td>
                  <td className="px-4 py-2.5 text-xs text-gray-800">王建国</td>
                  <td className="px-4 py-2.5 text-xs text-gray-600">肝脏移植</td>
                  <td className="px-4 py-2.5 text-xs">
                    <span className="text-green-600">正常</span>
                  </td>
                  <td className="px-4 py-2.5 text-xs text-gray-500">2026-03-12</td>
                </tr>
                <tr className="hover:bg-gray-50">
                  <td className="px-4 py-2.5 text-xs text-gray-600 font-mono">
                    OAS-2026-00203
                  </td>
                  <td className="px-4 py-2.5 text-xs text-gray-800">李秀兰</td>
                  <td className="px-4 py-2.5 text-xs text-gray-600">肾脏移植</td>
                  <td className="px-4 py-2.5 text-xs">
                    <span className="text-green-600">正常</span>
                  </td>
                  <td className="px-4 py-2.5 text-xs text-gray-500">2026-03-10</td>
                </tr>
                <tr className="hover:bg-gray-50">
                  <td className="px-4 py-2.5 text-xs text-gray-600 font-mono">
                    OAS-2026-00156
                  </td>
                  <td className="px-4 py-2.5 text-xs text-gray-800">张伟</td>
                  <td className="px-4 py-2.5 text-xs text-gray-600">心脏移植</td>
                  <td className="px-4 py-2.5 text-xs">
                    <span className="text-amber-600">观察中</span>
                  </td>
                  <td className="px-4 py-2.5 text-xs text-gray-500">2026-03-08</td>
                </tr>
              </tbody>
            </table>
          </div>
        </motion.div>
      </div>
    </div>
  );
}
