import { useEffect, useRef, useCallback } from 'react';
import { useGame } from '../GameContext';
import { SceneId } from '../GameContext';
import { Volume2, VolumeX } from 'lucide-react';

// 使用 Web Audio API 生成背景音乐，避免外部音频文件依赖
// 不同场景生成不同的合成音效

type BgmType = 'heartbeat' | 'ambient' | 'eerie' | 'tension' | 'none';

function getBgmForScene(scene: SceneId): BgmType {
  switch (scene) {
    case 'opening':
      return 'heartbeat';
    case 'oasLogin':
    case 'oasDashboard':
    case 'oasArchives':
    case 'oasAllocation':
    case 'oasFollowup':
    case 'oasAlerts':
    case 'shenchiPuzzle':
    case 'shenboPuzzle':
      return 'heartbeat';
    case 'instituteHome':
    case 'instituteAbout':
    case 'instituteNews':
    case 'instituteArchive':
    case 'heartCenter':
    case 'equipmentDept':
    case 'panyangHome':
    case 'panyangAbout':
    case 'panyangBusiness':
    case 'panyangProducts':
    case 'panyangNews':
    case 'panyangMap':
    case 'panyangContact':
      return 'ambient';
    case 'huaxiaForum':
    case 'door1Puzzle':
    case 'shibacengLogin':
      return 'none';
    case 'shibacengForum':
    case 'scripturePuzzle':
    case 'shenchiView':
    case 'shenboView':
    case 'finalDoor':
      return 'eerie';
    case 'endingChat':
    case 'badEnding':
    case 'goodEnding':
    case 'hiddenEnding':
      return 'tension';
    default:
      return 'ambient';
  }
}

export default function AudioController() {
  const { state, toggleMute } = useGame();
  const audioCtxRef = useRef<AudioContext | null>(null);
  const oscillatorsRef = useRef<OscillatorNode[]>([]);
  const gainNodesRef = useRef<GainNode[]>([]);
  const heartbeatIntervalRef = useRef<number | null>(null);
  const currentBgmRef = useRef<BgmType>('none');

  const stopAllAudio = useCallback(() => {
    if (heartbeatIntervalRef.current) {
      clearInterval(heartbeatIntervalRef.current);
      heartbeatIntervalRef.current = null;
    }
    oscillatorsRef.current.forEach((osc) => {
      try {
        osc.stop();
      } catch {
        // ignore
      }
    });
    oscillatorsRef.current = [];
    gainNodesRef.current = [];
    currentBgmRef.current = 'none';
  }, []);

  const playHeartbeat = useCallback(() => {
    if (!audioCtxRef.current) return;
    const ctx = audioCtxRef.current;

    // 播放一次心跳（咚——），包含：
    // 1. 主低音（sine 60Hz→30Hz，强冲击+长衰减）
    // 2. 次低频泛音（triangle 120Hz→80Hz，增加胸腔共鸣感）
    // 3. 极低频底噪（20Hz，增加厚重感）
    const playSingleBeat = (delay: number, intensity: number) => {
      if (currentBgmRef.current !== 'heartbeat') return;
      const t0 = ctx.currentTime + delay;

      // 主低音 —— 深沉有力的"咚"
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(65, t0);
      osc.frequency.exponentialRampToValueAtTime(28, t0 + 0.25);
      gain.gain.setValueAtTime(0, t0);
      gain.gain.linearRampToValueAtTime(1.2 * intensity, t0 + 0.015);
      gain.gain.exponentialRampToValueAtTime(0.6 * intensity, t0 + 0.08);
      gain.gain.exponentialRampToValueAtTime(0.001, t0 + 0.5);
      osc.connect(gain).connect(ctx.destination);
      osc.start(t0);
      osc.stop(t0 + 0.55);

      // 次低频泛音 —— 胸腔共鸣感
      const harmOsc = ctx.createOscillator();
      const harmGain = ctx.createGain();
      harmOsc.type = 'triangle';
      harmOsc.frequency.setValueAtTime(130, t0);
      harmOsc.frequency.exponentialRampToValueAtTime(60, t0 + 0.2);
      harmGain.gain.setValueAtTime(0, t0);
      harmGain.gain.linearRampToValueAtTime(0.35 * intensity, t0 + 0.02);
      harmGain.gain.exponentialRampToValueAtTime(0.001, t0 + 0.35);
      harmOsc.connect(harmGain).connect(ctx.destination);
      harmOsc.start(t0);
      harmOsc.stop(t0 + 0.4);

      // 极低频底噪 —— 胸腔震动的厚重感
      const subOsc = ctx.createOscillator();
      const subGain = ctx.createGain();
      subOsc.type = 'sine';
      subOsc.frequency.setValueAtTime(22, t0);
      subOsc.frequency.exponentialRampToValueAtTime(15, t0 + 0.4);
      subGain.gain.setValueAtTime(0, t0);
      subGain.gain.linearRampToValueAtTime(0.5 * intensity, t0 + 0.025);
      subGain.gain.exponentialRampToValueAtTime(0.001, t0 + 0.6);
      subOsc.connect(subGain).connect(ctx.destination);
      subOsc.start(t0);
      subOsc.stop(t0 + 0.65);
    };

    // 双跳节奏：咚——咚——（两声相似强度，模仿真实心跳 lub-dub 的厚重版）
    // 第一拍和第二拍间隔约 0.35s，整拍周期 1.2s
    const beatPattern = () => {
      playSingleBeat(0, 1.0);
      playSingleBeat(0.35, 0.85);
    };

    beatPattern();
    heartbeatIntervalRef.current = window.setInterval(beatPattern, 1200);
  }, []);

  const playAmbient = useCallback(() => {
    if (!audioCtxRef.current) return;
    const ctx = audioCtxRef.current;

    // 低频嗡鸣
    const osc1 = ctx.createOscillator();
    const gain1 = ctx.createGain();
    osc1.type = 'sine';
    osc1.frequency.value = 55;
    gain1.gain.value = 0.08;
    osc1.connect(gain1).connect(ctx.destination);
    osc1.start();

    // 中频泛音
    const osc2 = ctx.createOscillator();
    const gain2 = ctx.createGain();
    osc2.type = 'sine';
    osc2.frequency.value = 110;
    gain2.gain.value = 0.04;
    osc2.connect(gain2).connect(ctx.destination);
    osc2.start();

    oscillatorsRef.current.push(osc1, osc2);
    gainNodesRef.current.push(gain1, gain2);
  }, []);

  const playEerie = useCallback(() => {
    if (!audioCtxRef.current) return;
    const ctx = audioCtxRef.current;

    // 更低沉的低频
    const osc1 = ctx.createOscillator();
    const gain1 = ctx.createGain();
    osc1.type = 'sawtooth';
    osc1.frequency.value = 35;
    gain1.gain.value = 0.05;
    osc1.connect(gain1).connect(ctx.destination);
    osc1.start();

    // 缓慢漂动的高音
    const osc2 = ctx.createOscillator();
    const gain2 = ctx.createGain();
    osc2.type = 'sine';
    osc2.frequency.setValueAtTime(220, ctx.currentTime);
    osc2.frequency.linearRampToValueAtTime(180, ctx.currentTime + 8);
    gain2.gain.value = 0.03;
    osc2.connect(gain2).connect(ctx.destination);
    osc2.start();

    oscillatorsRef.current.push(osc1, osc2);
    gainNodesRef.current.push(gain1, gain2);
  }, []);

  const playTension = useCallback(() => {
    if (!audioCtxRef.current) return;
    const ctx = audioCtxRef.current;

    // 紧张感：低频脉冲
    const osc1 = ctx.createOscillator();
    const gain1 = ctx.createGain();
    osc1.type = 'square';
    osc1.frequency.value = 40;
    gain1.gain.setValueAtTime(0, ctx.currentTime);
    gain1.gain.linearRampToValueAtTime(0.04, ctx.currentTime + 2);
    osc1.connect(gain1).connect(ctx.destination);
    osc1.start();

    oscillatorsRef.current.push(osc1);
    gainNodesRef.current.push(gain1);
  }, []);

  const switchBgm = useCallback(
    (bgm: BgmType) => {
      if (state.muted) return;
      if (bgm === currentBgmRef.current) return;

      stopAllAudio();
      currentBgmRef.current = bgm;

      // 确保 AudioContext 已创建
      if (!audioCtxRef.current) {
        try {
          audioCtxRef.current = new (window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext)();
        } catch {
          return;
        }
      }

      // 恢复上下文（用户交互后）
      if (audioCtxRef.current.state === 'suspended') {
        audioCtxRef.current.resume();
      }

      switch (bgm) {
        case 'heartbeat':
          playHeartbeat();
          break;
        case 'ambient':
          playAmbient();
          break;
        case 'eerie':
          playEerie();
          break;
        case 'tension':
          playTension();
          break;
        default:
          break;
      }
    },
    [state.muted, stopAllAudio, playHeartbeat, playAmbient, playEerie, playTension]
  );

  // 场景切换时换 BGM
  useEffect(() => {
    const bgm = getBgmForScene(state.currentScene);
    switchBgm(bgm);
  }, [state.currentScene, switchBgm]);

  // 静音切换
  useEffect(() => {
    if (state.muted) {
      stopAllAudio();
    } else {
      const bgm = getBgmForScene(state.currentScene);
      currentBgmRef.current = 'none'; // 强制重新播放
      switchBgm(bgm);
    }
  }, [state.muted, state.currentScene, switchBgm, stopAllAudio]);

  // 清理
  useEffect(() => {
    return () => {
      stopAllAudio();
      if (audioCtxRef.current) {
        audioCtxRef.current.close();
      }
    };
  }, [stopAllAudio]);

  // 静音按钮不渲染 UI（由 CluePanel 或场景自行控制）
  // 此组件仅负责音频播放
  return (
    <button
      onClick={toggleMute}
      className="fixed bottom-4 left-4 z-[60] w-9 h-9 rounded-full bg-black/40 backdrop-blur-sm border border-white/10 text-white/80 hover:text-white hover:bg-black/60 transition-all flex items-center justify-center"
      aria-label={state.muted ? '取消静音' : '静音'}
      title={state.muted ? '取消静音' : '静音'}
    >
      {state.muted ? (
        <VolumeX className="w-4 h-4" />
      ) : (
        <Volume2 className="w-4 h-4" />
      )}
    </button>
  );
}


