import { useState, FormEvent } from 'react';
import { useGame } from '../GameContext';
import { motion } from 'framer-motion';
import { MOCK_STORY } from '@/data/story';
import { Building2, ArrowLeft, AlertCircle } from 'lucide-react';

export default function PanyangStaffLoginScene() {
  const { goToScene, goBack } = useGame();
  const { panyangStaff } = MOCK_STORY;
  const [employeeId, setEmployeeId] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState(false);
  const [loading, setLoading] = useState(false);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    setError(false);
    if (employeeId.toUpperCase() === 'PY068' && password === '686868') {
      setLoading(true);
      setTimeout(() => goToScene('panyangStaffHome'), 800);
    } else {
      setError(true);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-blue-50/30 flex flex-col">
      <button
        onClick={goBack}
        className="fixed top-4 left-4 z-50 flex items-center gap-1 text-sm text-gray-600 hover:text-blue-700 transition-colors"
      >
        <ArrowLeft className="w-4 h-4" />
        返回
      </button>

      <div className="flex-1 flex items-center justify-center px-4">
        <motion.div
          initial={{ opacity: 0, y: 12 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.4 }}
          className="w-full max-w-sm"
        >
          <div className="text-center mb-8">
            <div className="w-16 h-16 mx-auto mb-4 bg-white rounded-full shadow-sm border border-slate-200 flex items-center justify-center">
              <Building2 className="w-7 h-7 text-blue-700" />
            </div>
            <h1 className="text-lg font-medium text-slate-800">{panyangStaff.systemName}</h1>
            <p className="text-xs text-gray-500 mt-1">Panyang Bio · Employee Portal</p>
          </div>

          <div className="bg-white border border-slate-200 shadow-sm rounded-lg p-6">
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-xs text-gray-600 mb-1.5">员工号</label>
                <input
                  type="text"
                  value={employeeId}
                  onChange={(e) => setEmployeeId(e.target.value)}
                  className={`w-full h-9 px-3 text-sm border rounded-md bg-white outline-none transition-colors ${
                    error
                      ? 'border-red-400 focus:border-red-500'
                      : 'border-slate-300 focus:border-blue-600'
                  }`}
                  placeholder="请输入员工号"
                  autoFocus
                />
              </div>
              <div>
                <label className="block text-xs text-gray-600 mb-1.5">密码</label>
                <input
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className={`w-full h-9 px-3 text-sm border rounded-md bg-white outline-none transition-colors ${
                    error
                      ? 'border-red-400 focus:border-red-500'
                      : 'border-slate-300 focus:border-blue-600'
                  }`}
                  placeholder="请输入密码"
                />
              </div>

              {error && (
                <motion.p
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  className="text-xs text-red-500 flex items-center gap-1"
                >
                  <AlertCircle className="w-3.5 h-3.5" />
                  员工号或密码错误
                </motion.p>
              )}

              <button
                type="submit"
                disabled={loading}
                className="w-full h-9 bg-blue-700 text-white text-sm rounded-md hover:bg-blue-800 active:bg-blue-900 transition-colors disabled:opacity-60"
              >
                {loading ? '登录中...' : '登 录'}
              </button>
            </form>

            <div className="mt-5 pt-4 border-t border-slate-100">
              <p className="text-[11px] text-gray-400 leading-relaxed">
                仅限内部员工使用，首次登录请绑定OA账号
              </p>
            </div>
          </div>

          <p className="text-center text-[11px] text-gray-400 mt-6">
            © 2026 盘阳生物科技有限公司 · 信息安全部
          </p>
        </motion.div>
      </div>
    </div>
  );
}
