import { useState, useEffect } from 'react';
import { useGame } from '../GameContext';
import { motion, AnimatePresence } from 'framer-motion';

interface LogEntry {
  date: string;
  surname: string;
  givenName: string;
  age: string;
  location: string;
  count: string;
  crossed?: boolean;
}

const PAGES: LogEntry[][] = [
  // 第 1 页：前 2006 年几个，全是 74
  [
    { date: '二〇〇六·〇三·一七', surname: '李', givenName: '—', age: '七十二', location: '西安', count: '74' },
    { date: '二〇〇六·〇五·二二', surname: '王', givenName: '—', age: '五十八', location: '西安', count: '74' },
    { date: '二〇〇六·〇八·〇九', surname: '张', givenName: '—', age: '八十三', location: '西安', count: '74' },
    { date: '二〇〇六·一〇·三', surname: '刘', givenName: '—', age: '六十四', location: '西安', count: '74' },
  ],
  // 第 2 页：沈迟 6 岁那次（划掉 74，写 77）
  [
    { date: '二〇〇六·一一·〇八', surname: '沈', givenName: '—', age: '六', location: '西安', count: '74', crossed: true },
    { date: '二〇〇六·一一·〇八', surname: '沈', givenName: '—', age: '六', location: '西安', count: '77' },
    { date: '二〇〇七·〇二·一四', surname: '陈', givenName: '—', age: '七十九', location: '西安', count: '74' },
    { date: '二〇〇八·〇七·三〇', surname: '赵', givenName: '—', age: '七十一', location: '西安', count: '74' },
  ],
  // 第 3 页：沈迟 14 岁
  [
    { date: '二〇一四·〇七·二二', surname: '沈', givenName: '—', age: '十四', location: '西安', count: '77' },
    { date: '二〇一六·一二·五', surname: '孙', givenName: '—', age: '六十六', location: '西安', count: '74' },
    { date: '二〇一九·〇四·一八', surname: '周', givenName: '—', age: '八十二', location: '西安', count: '74' },
    { date: '二〇二〇·〇九·七', surname: '吴', givenName: '—', age: '五十七', location: '西安', count: '74' },
  ],
  // 第 4 页：沈迟 26 岁
  [
    { date: '二〇二六·〇九·一二', surname: '沈', givenName: '沈迟', age: '二十六', location: '西安', count: '77' },
    { date: '二〇二七·〇三·二五', surname: '郑', givenName: '—', age: '六十三', location: '西安', count: '74' },
    { date: '二〇二八·一一·九', surname: '钱', givenName: '—', age: '七十四', location: '西安', count: '74' },
  ],
  // 第 5 页：沈搏母亲 68（划掉 74，写 68）
  [
    { date: '二〇二九·一一·〇四', surname: '—', givenName: '—', age: '六十三', location: '西安', count: '74', crossed: true },
    { date: '二〇二九·一一·〇四', surname: '沈', givenName: '沈搏', age: '二十九', location: '西安', count: '68' },
    { date: '二〇三〇·一·一七', surname: '冯', givenName: '—', age: '七十八', location: '西安', count: '74' },
    { date: '二〇三〇·六·三', surname: '褚', givenName: '—', age: '六十九', location: '西安', count: '74' },
  ],
  // 第 6 页（最后一页）：空表格，等你填
  [
    { date: '', surname: '', givenName: '', age: '', location: '', count: '' },
    { date: '', surname: '', givenName: '', age: '', location: '', count: '' },
    { date: '', surname: '', givenName: '', age: '', location: '', count: '' },
    { date: '', surname: '', givenName: '', age: '', location: '', count: '' },
  ],
];

const PAGE_NOTES = [
  '',
  '',
  '',
  '',
  '倒数第二页',
  '还差一个人。',
  '', // 最后揭示页
];

export default function DutyKeeperScene() {
  const { goBack } = useGame();
  const [currentPage, setCurrentPage] = useState(0);
  const [showHand, setShowHand] = useState(true);
  const [isWriting, setIsWriting] = useState(false);

  useEffect(() => {
    const t = setTimeout(() => setShowHand(false), 2800);
    return () => clearTimeout(t);
  }, []);

  // 最后一页的揭示——停留后逐渐浮现
  const [lastPageRevealed, setLastPageRevealed] = useState(false);

  const isLastPage = currentPage === PAGES.length - 1;
  const isSecondLast = currentPage === PAGES.length - 2;

  useEffect(() => {
    if (isLastPage) {
      const t = setTimeout(() => setLastPageRevealed(true), 2500);
      return () => clearTimeout(t);
    } else {
      setLastPageRevealed(false);
    }
  }, [currentPage, isLastPage]);

  const turnPage = (dir: number) => {
    const next = currentPage + dir;
    if (next < 0 || next >= PAGES.length) return;
    setIsWriting(true);
    setTimeout(() => {
      setCurrentPage(next);
      setIsWriting(false);
    }, 450);
  };

  return (
    <div className="relative w-full min-h-screen bg-[hsl(30_20%_92%)] overflow-hidden">
      {/* 走廊背景——浅绿冷光，模糊 */}
      <div className="absolute inset-0 bg-gradient-to-b from-[hsl(180_15%_85%)]/40 via-[hsl(200_10%_88%)]/60 to-[hsl(210_15%_82%)]/80" />

      {/* 顶部通风管的荧光灯感 */}
      <div className="absolute top-0 left-0 right-0 h-16 bg-gradient-to-b from-[hsl(60_30%_92%)]/50 to-transparent" />

      {/* 返回按钮 */}
      <button
        onClick={goBack}
        className="absolute top-4 left-4 z-30 text-xs text-slate-500 hover:text-slate-700 transition-colors"
      >
        ← 回到走廊
      </button>

      {/* 本子主体 */}
      <div className="relative z-10 flex flex-col items-center justify-center min-h-screen px-4 py-12">
        {/* 手的剪影——只给一只拿笔的手和本子，永远低着头 */}
        {showHand && (
          <div className="absolute top-24 right-[15%] z-20 pointer-events-none animate-[fadeout_2.8s_ease-in_forwards]">
            <div className="text-right">
              {/* 铅笔 */}
              <div className="inline-block w-24 h-1.5 bg-red-700/60 rounded-full transform rotate-12 shadow-sm" />
              {/* 手腕阴影 */}
              <div className="mt-2 w-20 h-12 bg-stone-300/40 rounded-bl-full ml-auto blur-sm" />
            </div>
            <p className="text-[10px] text-stone-500/70 mt-1 italic">
              ——她一直低着头在写。
            </p>
          </div>
        )}

        {/* 页码 */}
        <div className="text-[11px] text-stone-500 mb-2 font-mono tracking-widest">
          第 {currentPage + 1} / {PAGES.length} 页
        </div>

        {/* 牛皮纸本子 */}
        <div
          className={`
            relative w-full max-w-2xl bg-[hsl(40_30%_90%)] rounded-sm
            shadow-[0_8px_32px_rgba(0_0_0_0.15)]
            border border-[hsl(35_25%_75%)]
            transition-all duration-500 ease-out
            ${isWriting ? 'opacity-50 translate-y-1' : 'opacity-100 translate-y-0'}
          `}
        >
          {/* 纸纹 */}
          <div
            className="absolute inset-0 opacity-30 pointer-events-none"
            style={{
              backgroundImage: `repeating-linear-gradient(
                0deg,
                transparent,
                transparent 28px,
                hsl(35_20%_75%) 28px,
                hsl(35_20%_75%) 28.5px
              )`,
            }}
          />

          {/* 装订线 */}
          <div className="absolute left-8 top-0 bottom-0 w-px bg-stone-400/40" />

          {/* 本子内容 */}
          <div className="relative p-8 pl-12">
             {/* 扉页风格标题——只在第一页 */}
             {currentPage === 0 && (
               <div className="text-center mb-8">
                 <p className="text-4xl font-serif text-stone-700 tracking-[0.5em] mb-2">数</p>
                 <p className="text-[10px] text-stone-500 tracking-widest">临渊研究所 · 三楼东走廊</p>
                 <p className="text-[9px] text-stone-400/80 mt-3 tracking-wider italic">
                   「太吵了」<br/>
                   「我记一下」
                 </p>
               </div>
             )}

            {/* 表头 */}
            <div className="grid grid-cols-[1.2fr_0.5fr_1fr_0.6fr_0.7fr_0.5fr] gap-1 text-[11px] text-stone-500 border-b border-stone-400/50 pb-1 mb-2 font-serif">
              <span>日期</span>
              <span>姓</span>
              <span>名</span>
              <span>年龄</span>
              <span>地点</span>
              <span className="text-right">数</span>
            </div>

            {/* 表格行 */}
            <div className="space-y-1.5 font-serif">
              {PAGES[currentPage].map((entry, idx) => (
                <div
                  key={idx}
                  className="grid grid-cols-[1.2fr_0.5fr_1fr_0.6fr_0.7fr_0.5fr] gap-1 text-[13px] text-stone-700 py-0.5 border-b border-dashed border-stone-300/50"
                >
                  <span className="truncate">{entry.date || '\u00A0'}</span>
                  <span>{entry.surname || '\u00A0'}</span>
                  <span className="truncate">{entry.givenName || '\u00A0'}</span>
                  <span>{entry.age || '\u00A0'}</span>
                  <span className="truncate">{entry.location || '\u00A0'}</span>
                  <span
                    className={`
                      text-right tabular-nums
                      ${entry.crossed ? 'line-through text-stone-400' : ''}
                      ${entry.count === '77' ? 'text-red-300 font-medium' : ''}
                      ${entry.count === '68' ? 'text-rose-700 font-medium' : ''}
                      ${!entry.count ? 'text-stone-300' : ''}
                    `}
                  >
                    {entry.count || '\u00A0'}
                  </span>
                </div>
              ))}
            </div>

            {/* 页脚备注 */}
            {PAGE_NOTES[currentPage] && (
              <div className="mt-8 pt-2 border-t border-stone-300/40">
                <p className={`text-xs text-stone-500 italic font-serif ${isLastPage ? 'text-stone-400 text-right' : ''}`}>
                  {PAGE_NOTES[currentPage]}
                </p>
              </div>
            )}

            {/* 最后一页——空表格的提示 */}
             {isLastPage && (
               <div className="mt-6 text-center">
                 <p className="text-[11px] text-stone-400 tracking-widest">
                   ——表格画好了，五栏都在，数那栏空着——
                 </p>
                 <p className="text-[11px] text-stone-400/70 mt-2 italic">
                   等你自己坐下来的时候，被记上。
                 </p>

                 {/* 最后一页的揭示——慢慢浮现 */}
                 <AnimatePresence>
                   {lastPageRevealed && (
                     <motion.div
                       initial={{ opacity: 0 }}
                       animate={{ opacity: 1 }}
                       transition={{ duration: 2.5 }}
                       className="mt-8 pt-6 border-t border-stone-300/60 text-left"
                     >
                       {/* 表格最后一行——手写的沈搏 */}
                       <div className="grid grid-cols-[1.2fr_0.5fr_1fr_0.6fr_0.7fr_0.5fr] gap-1 text-[13px] text-rose-800/80 font-serif py-0.5">
                         <span className="truncate">&nbsp;</span>
                         <span>沈</span>
                         <span className="truncate">沈搏</span>
                         <span>—</span>
                         <span className="truncate">&nbsp;</span>
                         <span className="text-right tabular-nums">—</span>
                       </div>

                       <p className="text-[11px] text-stone-500/70 italic mt-6 text-right font-serif">
                         本子最后一页没有编号。
                       </p>
                       <p className="text-[11px] text-stone-500/70 italic text-right font-serif">
                         只用铅笔写了一行字——
                       </p>
                       <p className="text-sm text-rose-800/70 italic mt-2 text-right font-serif">
                         我儿子回来了。
                       </p>

                       <div className="mt-6 pt-4 border-t border-stone-300/40">
                         <p className="text-[10px] text-stone-500/60 italic font-serif">
                           她叫张桂兰。
                         </p>
                         <p className="text-[10px] text-stone-500/60 italic font-serif">
                           六十七岁那年走的，
                         </p>
                         <p className="text-[10px] text-stone-500/60 italic font-serif">
                           走的那天晚上，
                         </p>
                         <p className="text-[10px] text-stone-500/60 italic font-serif">
                           医院的钟停了六十八秒。
                         </p>
                         <p className="text-[10px] text-rose-700/50 italic mt-2 font-serif">
                           她的意识留在了走廊里，
                         </p>
                         <p className="text-[10px] text-rose-700/50 italic font-serif">
                           一直记名字，
                         </p>
                         <p className="text-[10px] text-rose-700/50 italic font-serif">
                           等她儿子下次来。
                         </p>
                       </div>
                     </motion.div>
                   )}
                 </AnimatePresence>
               </div>
             )}

            {/* 落款——永远空着，只写「值班的」 */}
            <div className="mt-8 text-right">
              <p className="text-xs text-stone-500/60 font-serif italic">
                {isSecondLast ? '—— 值班的' : isLastPage ? '—— （签 名）' : '—— 值班的'}
              </p>
            </div>
          </div>
        </div>

        {/* 翻页控制 */}
        <div className="flex items-center gap-8 mt-6">
          <button
            onClick={() => turnPage(-1)}
            disabled={currentPage === 0}
            className={`
              text-xs font-serif transition-colors
              ${currentPage === 0
                ? 'text-stone-300 cursor-default'
                : 'text-stone-500 hover:text-stone-700'
              }
            `}
          >
            ← 上一页
          </button>

          {/* 页码点 */}
          <div className="flex gap-1.5">
            {PAGES.map((_, i) => (
              <button
                key={i}
                onClick={() => {
                  setIsWriting(true);
                  setTimeout(() => {
                    setCurrentPage(i);
                    setIsWriting(false);
                  }, 450);
                }}
                className={`
                  w-1.5 h-1.5 rounded-full transition-colors
                  ${i === currentPage ? 'bg-stone-500' : 'bg-stone-300 hover:bg-stone-400'}
                `}
                aria-label={`第 ${i + 1} 页`}
              />
            ))}
          </div>

          <button
            onClick={() => turnPage(1)}
            disabled={currentPage === PAGES.length - 1}
            className={`
              text-xs font-serif transition-colors
              ${currentPage === PAGES.length - 1
                ? 'text-stone-300 cursor-default'
                : 'text-stone-500 hover:text-stone-700'
              }
            `}
          >
            下一页 →
          </button>
        </div>

        {/* 底部一行小字 */}
        <p className="mt-10 text-[10px] text-stone-400 tracking-wider font-serif italic">
          她永不给正脸。只给一只拿笔的手，和一本记不完的本子。
        </p>
      </div>

      <style>{`
        @keyframes fadeout {
          0% { opacity: 1; transform: translateY(0); }
          70% { opacity: 1; }
          100% { opacity: 0; transform: translateY(-4px); }
        }
      `}</style>
    </div>
  );
}
