const PAN_NAV = [
  { id: 'home', label: '首页', icon: Home },
  { id: 'about', label: '关于我们', icon: Building2 },
  { id: 'business', label: '业务领域', icon: Briefcase },
  { id: 'products', label: '产品中心', icon: Package },
  { id: 'news', label: '新闻中心', icon: Newspaper },
  { id: 'map', label: '全国布局', icon: MapPin },
  { id: 'contact', label: '联系我们', icon: Phone },
] as const;

type PanTabId = (typeof PAN_NAV)[number]['id'];

interface PanyangBioSceneProps {
  initialTab?: PanTabId;
}

export default function PanyangBioScene({ initialTab = 'home' }: PanyangBioSceneProps) {
  const { findClue, state, goToScene } = useGame();
  const [activeTab, setActiveTab] = useState<PanTabId>(initialTab);
  const { panyangBio } = MOCK_STORY;

  // 在全国布局页发现线索
  const handleMapClick = () => {
    setActiveTab('map');
    if (!state.clues.cityList.found) {
      setTimeout(() => {
        findClue('cityList', 'panyangMap' as SceneId);
      }, 1000);
    }
  };

  return (
    <div className="min-h-screen bg-white">
      <SceneChrome title={panyangBio.companyName} variant="light" />

      {/* 顶部导航 */}
      <div className="fixed top-12 md:top-14 left-0 right-0 z-40 bg-white/95 backdrop-blur-sm border-b border-slate-100 overflow-x-auto">
        <div className="flex items-center min-w-max px-2 md:px-6 max-w-6xl mx-auto">
          <div className="flex items-center gap-2 pr-4 mr-2 border-r border-slate-200">
            <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-blue-500 to-cyan-500 flex items-center justify-center">
              <span className="text-white text-xs font-bold">PY</span>
            </div>
            <span className="font-semibold text-slate-800 text-sm hidden sm:inline">盘阳生物</span>
          </div>
          {PAN_NAV.map((tab) => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.id;
            return (
              <button
                key={tab.id}
                onClick={() => {
                  if (tab.id === 'map') {
                    handleMapClick();
                  } else {
                    setActiveTab(tab.id);
                  }
                }}
                className={`flex items-center gap-1.5 px-3 py-3 text-sm whitespace-nowrap border-b-2 transition-colors ${
                  isActive
                    ? 'border-blue-600 text-blue-700 font-medium'
                    : 'border-transparent text-slate-600 hover:text-slate-900'
                }`}
              >
                <Icon className="w-3.5 h-3.5" />
                <span className="hidden md:inline">{tab.label}</span>
                <span className="md:hidden">{tab.label.slice(0, 2)}</span>
              </button>
            );
          })}
        </div>
      </div>

      {/* 内容区 */}
      <div className="pt-28 pb-12">
        <AnimatePresence mode="wait">
          <motion.div
            key={activeTab}
            initial={{ opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -8 }}
            transition={{ duration: 0.3 }}
            className="max-w-5xl mx-auto px-3 md:px-6"
          >
            {activeTab === 'home' && <PanyangHome onNavigate={setActiveTab} />}
            {activeTab === 'about' && <PanyangAbout />}
            {activeTab === 'business' && <PanyangBusiness goToScene={goToScene} />}
            {activeTab === 'products' && <PanyangProducts />}
            {activeTab === 'news' && <PanyangNews goToScene={goToScene} />}
            {activeTab === 'map' && <PanyangMap goToScene={goToScene} />}
            {activeTab === 'contact' && <PanyangContact />}
          </motion.div>
        </AnimatePresence>
      </div>
    </div>
  );
}

