import { useState, FormEvent, useEffect } from 'react';
import { SceneId, useGame } from '../GameContext';
import { atbashCipher } from '../lib/puzzleUtils';
import { motion, AnimatePresence } from 'framer-motion';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { BookOpen, Lock, AlertTriangle, Eye, CheckCircle2 } from 'lucide-react';
import { toast } from 'sonner';
import SceneChrome from '../components/SceneChrome';
import { MOCK_STORY } from '@/data/story';

const SCRIPTURE_CIPHER = 'EVHHVO'; // VESSEL 的 Atbash 加密
const SCRIPTURE_ANSWER = 'VESSEL';

export default function ScripturePuzzleScene() {
  const { goBack, goToScene, setPuzzleDone, state, findClue } = useGame();
  const [input, setInput] = useState('');
  const [error, setError] = useState('');
  const [solved, setSolved] = useState(false);
  const [showHint, setShowHint] = useState(false);
  const { shibaceng } = MOCK_STORY;

  useEffect(() => {
    if (state.puzzleProgress.scripturePuzzle) {
      setSolved(true);
    }
  }, [state.puzzleProgress.scripturePuzzle]);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const answer = input.trim().toUpperCase();
    if (answer === SCRIPTURE_ANSWER) {
      setSolved(true);
      setPuzzleDone('scripturePuzzle');
      findClue('scripture', 'scripturePuzzle' as SceneId);
      toast.success('经书密文已解开');
      setError('');
    } else {
      setError('密文未解开，再想想...');
    }
  };

  const handleShowHint = () => {
    setShowHint(true);
  };

  return (
    <div className="min-h-screen bg-black text-red-200 relative overflow-hidden">
      <SceneChrome title="经书解密" variant="dark" />

      {/* 背景装饰 */}
      <div className="fixed inset-0 pointer-events-none">
        <div className="absolute top-1/4 left-1/2 -translate-x-1/2 w-[500px] h-[500px] opacity-5">
          <svg viewBox="0 0 200 200" className="w-full h-full">
            <polygon points="100,10 180,150 20,150" fill="none" stroke="#dc2626" strokeWidth="0.5" />
            <polygon points="100,190 20,50 180,50" fill="none" stroke="#dc2626" strokeWidth="0.5" />
          </svg>
        </div>
      </div>

      <div className="pt-20 pb-12 px-4 max-w-2xl mx-auto relative z-10">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
          className="space-y-8"
        >
          {/* 标题 */}
          <div className="text-center">
            <BookOpen className="w-12 h-12 text-red-600 mx-auto mb-4" />
            <h1 className="text-2xl font-bold text-red-400 tracking-wider mb-2">
              经 书 密 文
            </h1>
            <p className="text-red-800 text-sm">将密文还原为明文</p>
          </div>

          {/* 经文卷轴 */}
          <div className="p-6 md:p-8 bg-gradient-to-b from-red-950/40 to-black border border-red-900/30 rounded-lg">
            <div className="text-center mb-6">
              <p className="text-xs text-red-800 mb-4">——《十八层教义·卷二·密卷》——</p>
               <div className="text-xl md:text-2xl font-bold tracking-[0.5em] text-red-400 mb-4">
                  {SCRIPTURE_CIPHER}
               </div>
               <p className="text-sm text-red-700 leading-relaxed">
                 古卷的注脚说：希伯来人写字母的时候，
                 <br />
                 第一个字母对着最后一个，
                 <br />
                 第二个对着倒数第二个，
                 <br />
                 他们管这个叫反向的约定。
               </p>
               <p className="text-xs text-red-800 mt-2">
                 六个字母。答案是一个词。
               </p>
            </div>

            {showHint && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                className="p-4 bg-black/50 border border-red-900/30 rounded text-xs space-y-1"
              >
                <p className="text-red-600 mb-2">💡 提示：这是一种最古老的替换密码之一，它的名字来自希伯来语"אתבש"。把字母表对折，首尾互换就是全部规则。</p>
                <p className="text-red-500/80">举个例子：A→Z，B→Y，C→X……以此类推。</p>
              </motion.div>
            )}

            <button
              onClick={() => setShowHint(!showHint)}
              className="w-full text-center text-xs text-red-800 hover:text-red-600 transition-colors py-2"
            >
              {showHint ? '收起提示' : '我需要一点提示'}
            </button>
          </div>

          {/* 解密输入 */}
          <div className="p-6 bg-black/50 border border-red-900/30 rounded-lg">
            <h3 className="text-sm font-medium text-red-400 mb-4 flex items-center gap-2">
              <Lock className="w-4 h-4" />
              输入解密后的明文
            </h3>

            <form onSubmit={handleSubmit} className="space-y-4">
              <Input
                type="text"
                value={input}
                onChange={(e) => {
                  setInput(e.target.value);
                  setError('');
                }}
                placeholder="请输入答案（英文）"
                className="bg-red-950/30 border-red-900/50 text-red-200 placeholder:text-red-900/60 focus:border-red-500 focus:ring-red-500/20 text-center tracking-[0.3em] uppercase"
                disabled={solved}
              />

              <AnimatePresence>
                {error && (
                  <motion.p
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    className="text-sm text-red-500 flex items-center gap-2 justify-center"
                  >
                    <AlertTriangle className="w-4 h-4" />
                    {error}
                  </motion.p>
                )}
              </AnimatePresence>

              {!solved ? (
                <Button
                  type="submit"
                  className="w-full bg-red-600/80 hover:bg-red-600 text-white border border-red-500/50 h-11"
                >
                  解 密
                </Button>
              ) : (
                <motion.div
                  initial={{ opacity: 0, scale: 0.95 }}
                  animate={{ opacity: 1, scale: 1 }}
                  className="space-y-4"
                >
                  <div className="flex items-center justify-center gap-2 text-green-400 py-2">
                    <CheckCircle2 className="w-5 h-5" />
                    <span>解密成功</span>
                  </div>

                   {/* 解密结果展示 */}
                   <div className="p-4 bg-red-950/50 border border-red-800/50 rounded-lg text-left space-y-3">
                     <p className="text-xs text-red-500 mb-1 text-center">—— 解密结果 ——</p>
                     <p className="text-xl font-bold tracking-[0.3em] text-red-400 text-center">
                       {SCRIPTURE_ANSWER}
                     </p>
                       <p className="text-sm text-red-300/80 text-center">
                         = 容器 / 器皿 / 血管
                       </p>
                         <div className="pt-3 border-t border-red-900/50 space-y-3 text-xs text-red-300/70 leading-relaxed">
                           <p>——《十八层本纪·第七十四章》——</p>
                           <p>希伯来人写 leb，阿拉伯人写 قلب，埃及人把脑子掏出来丢掉只留下心脏，中国人刻下「心藏神」，印度人说 citta，苏美人按下楔形，北欧人念出 rune。</p>
                           <p>九种文明，九种语言，隔着山隔着海，各自造出了同一个东西——</p>
                           <p className="text-red-400">一个用来装它的器皿。</p>
                           <p>瓦罐、铜鼎、石龛、心跳的胸腔、活人的血肉——</p>
                           <p>他们都在找一个能盛下它的容器。</p>
                           <p>他们都以为自己造出了神的居所。</p>
                           <p className="text-red-400">但神根本不需要居所。</p>
                           <p>神只是在睡觉。</p>
                           <p>那些被狂热人类捧起来的、用来献祭的、以为能装下它的活人——</p>
                           <p>不过是它翻身时，随手压到的一只蚊子。</p>
                           <p>十八层在找的不是钥匙，不是门，不是仪式。</p>
                           <p>是一个足够结实的器皿。</p>
                           <p>一个能在它醒过来的时候，</p>
                           <p className="text-red-400">不被撑碎的容器。</p>
                           <p>七十四次转移，七十四次失败。</p>
                           <p>每一颗心脏都在它翻个身的瞬间，像瓦罐一样碎了。</p>
                           <p>沈迟是现任持有者。</p>
                           <p>他术后听见的数数声，不是它来了。</p>
                           <p>是它在试这个罐子结不结实。</p>
                           <p>沈搏机器里那68秒波形，不是母亲的余晖。</p>
                           <p>是它迷迷糊糊伸手碰了一下罐子，又缩了回去。</p>
                           <p className="text-red-500">而你，程未，是下一个预定的容器。</p>
                           <p>你配型完全吻合，</p>
                           <p>又查档案查得太深了。</p>
                           <p>他们打算等沈迟术后稳定，</p>
                           <p className="text-red-500">就装上控制芯片，再把这颗心换到你身上。</p>
                         </div>
                   </div>

                  <Button
                     type="button"
                     onClick={goBack}
                     className="w-full bg-red-900/50 hover:bg-red-900/70 text-red-200 border border-red-800/50 h-11"
                   >
                     返回十八层
                   </Button>
                </motion.div>
              )}
            </form>
          </div>

          {/* 剧情提示 */}
          <p className="text-center text-xs text-red-900/60">
            解开密文后，隐藏的手记将浮出水面...
          </p>
        </motion.div>
      </div>
    </div>
  );
}
