import { useState } from 'react';
import { Home, GitBranch, FileArchive, User, Menu, X } from 'lucide-react';

interface OasPatientTopNavProps {
  activeTab: string;
  onTabChange: (tab: string) => void;
  patientName: string;
  onLogout?: () => void;
}

const NAV_TABS = [
  { id: 'home', label: '首页', icon: Home },
  { id: 'matching', label: '匹配记录', icon: GitBranch },
  { id: 'archive', label: '分配档案', icon: FileArchive },
  { id: 'profile', label: '个人中心', icon: User },
];

export default function OasPatientTopNav({ activeTab, onTabChange, patientName, onLogout }: OasPatientTopNavProps) {
  const [mobileOpen, setMobileOpen] = useState(false);

  return (
    <div className="pt-12 bg-[#1e5b9d] border-b border-[#154a82] sticky top-0 z-40">
      <div className="max-w-5xl mx-auto px-4 flex items-center justify-between text-sm text-blue-200">
        {/* 左侧 logo */}
        <div className="flex items-center gap-2 py-2.5">
          <div className="w-7 h-7 bg-white/10 rounded flex items-center justify-center border border-blue-400/30">
            <span className="text-white text-xs font-bold">OAS</span>
          </div>
          <div className="hidden md:block">
            <span className="text-white font-medium text-sm">全国器官分配与共享系统</span>
            <span className="text-blue-300/60 text-xs ml-2">· 患者服务端</span>
          </div>
          <span className="text-white font-medium md:hidden">OAS患者端</span>
        </div>

        {/* 桌面端导航 */}
        <div className="hidden md:flex items-center gap-1">
          {NAV_TABS.map((tab) => {
            const Icon = tab.icon;
            return (
              <button
                key={tab.id}
                onClick={() => onTabChange(tab.id)}
                className={`flex items-center gap-1.5 py-2.5 px-3 whitespace-nowrap transition-colors ${
                  activeTab === tab.id
                    ? 'text-white border-b-2 border-white font-medium'
                    : 'hover:text-white'
                }`}
              >
                <Icon className="w-3.5 h-3.5" />
                {tab.label}
              </button>
            );
          })}
        </div>

        {/* 右侧用户 */}
        <div className="hidden md:flex items-center gap-3">
          <span className="text-xs">{patientName} 先生</span>
          <div className="w-6 h-6 rounded-full bg-blue-400 flex items-center justify-center text-xs text-white">
            {patientName[0]}
          </div>
          {onLogout && (
            <button
              onClick={onLogout}
              className="ml-2 text-xs text-blue-200 hover:text-white transition-colors"
            >
              退出登录
            </button>
          )}
        </div>

        {/* 移动端菜单 */}
        <button
          className="md:hidden text-white p-1"
          onClick={() => setMobileOpen(!mobileOpen)}
        >
          {mobileOpen ? <X className="w-5 h-5" /> : <Menu className="w-5 h-5" />}
        </button>
      </div>

      {/* 移动端展开 */}
      {mobileOpen && (
        <div className="md:hidden border-t border-[#154a82] bg-[#1e5b9d]">
          {NAV_TABS.map((tab) => {
            const Icon = tab.icon;
            return (
              <button
                key={tab.id}
                onClick={() => {
                  onTabChange(tab.id);
                  setMobileOpen(false);
                }}
                className={`w-full flex items-center gap-3 px-4 py-3 text-sm border-b border-[#154a82]/50 ${
                  activeTab === tab.id
                    ? 'text-white bg-[#154a82]/50'
                    : 'text-blue-200'
                }`}
              >
                <Icon className="w-4 h-4" />
                {tab.label}
              </button>
            );
          })}
          <div className="px-4 py-3 flex items-center gap-2 text-xs text-blue-200">
            <div className="w-6 h-6 rounded-full bg-blue-400 flex items-center justify-center text-white">
              {patientName[0]}
            </div>
            <div className="flex-1">{patientName} 先生</div>
            {onLogout && (
              <button onClick={onLogout} className="text-blue-200 hover:text-white">
                退出
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
