function getResponse(question: string): string[] {
  const q = question.toLowerCase();

  // 优先级匹配
  if (q.includes('谁') || q.includes('你是') || q.includes('who')) return IT_RESPONSES.who;
  if (q.includes('74') || q.includes('68') || q.includes('数字') || q.includes('为什么是')) return IT_RESPONSES.why74;
  if (q.includes('沈迟') || q.includes('心脏') || q.includes('幻听')) return IT_RESPONSES.shenchi;
  if (q.includes('沈搏') || q.includes('仪器') || q.includes('维修') || q.includes('yqsm')) return IT_RESPONSES.shenbo;
  if (q.includes('12') || q.includes('城市') || q.includes('手') || q.includes('盘阳') || q.includes('十二')) return IT_RESPONSES.twelve;
  if (q.includes('3:47') || q.includes('三点') || q.includes('凌晨') || q.includes('失眠') || q.includes('醒')) return IT_RESPONSES.time347;
  if (q.includes('在哪') || q.includes('哪里') || q.includes('where') || q.includes('behind') || q.includes('身后') || q.includes('在这里')) return IT_RESPONSES.where;
  if (q.includes('研究所') || q.includes('临渊') || q.includes('殡仪馆') || q.includes('地址')) return IT_RESPONSES.research;
  if (q.includes('姐姐') || q.includes('程遥') || q.includes('妹') || q.includes('姐') || q.includes('走丢')) return IT_RESPONSES.sister;
  if (q.includes('什么') || q.includes('想') || q.includes('要') || q.includes('what') || q.includes('目的')) return IT_RESPONSES.what;

  return IT_RESPONSES.default;
}

export default function EndingChatScene() {
  const { state, goToScene, allCluesFound, setFakeEndingEntry } = useGame();
  const shenchiLineUnlocked = state.puzzleProgress.shenchiLineUnlocked;
  const shenboLineUnlocked = state.puzzleProgress.shenboLineUnlocked;
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [roundCount, setRoundCount] = useState(0);
  const [showChoice, setShowChoice] = useState(false);
  const [revealedTopics, setRevealedTopics] = useState<Set<string>>(new Set());
  const chatEndRef = useRef<HTMLDivElement>(null);

  // 初始问候
  useEffect(() => {
    const timer = setTimeout(() => {
      addItMessage('你来了。');
    }, 1000);
    const timer2 = setTimeout(() => {
      addItMessage('我等你很久了，程未。');
    }, 2500);
    return () => {
      clearTimeout(timer);
      clearTimeout(timer2);
    };
  }, []);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isTyping]);

  const addItMessage = (text: string) => {
    setMessages((prev) => [
      ...prev,
      { id: `it-${Date.now()}-${Math.random()}`, sender: 'it', text },
    ]);
  };

  const detectTopic = (question: string): string => {
    const q = question.toLowerCase();
    if (q.includes('谁') || q.includes('你是') || q.includes('who')) return 'who';
    if (q.includes('74') || q.includes('68') || q.includes('数字')) return 'why74';
    if (q.includes('沈迟') || q.includes('心脏') || q.includes('幻听')) return 'shenchi';
    if (q.includes('沈搏') || q.includes('仪器') || q.includes('维修') || q.includes('yqsm')) return 'shenbo';
    if (q.includes('12') || q.includes('城市') || q.includes('手') || q.includes('盘阳') || q.includes('十二')) return 'twelve';
    if (q.includes('3:47') || q.includes('三点') || q.includes('凌晨') || q.includes('失眠') || q.includes('醒')) return 'time347';
    if (q.includes('在哪') || q.includes('哪里') || q.includes('where') || q.includes('behind') || q.includes('身后')) return 'where';
    if (q.includes('研究所') || q.includes('临渊') || q.includes('殡仪馆') || q.includes('地址')) return 'research';
    if (q.includes('姐姐') || q.includes('程遥') || q.includes('姐') || q.includes('走丢')) return 'sister';
    if (q.includes('什么') || q.includes('想') || q.includes('要') || q.includes('what') || q.includes('目的')) return 'what';
    return 'default';
  };

  const sendMessage = (text: string) => {
    if (!text.trim() || isTyping || showChoice) return;
    const question = text.trim();
    setMessages((prev) => [
      ...prev,
      { id: `player-${Date.now()}`, sender: 'player', text: question },
    ]);
    setInput('');
    setIsTyping(true);
    setRoundCount((r) => r + 1);

    const topic = detectTopic(question);
    const responses = getResponse(question);
    setRevealedTopics((prev) => new Set(prev).add(topic));

    let idx = 0;

    const sendNext = () => {
      if (idx >= responses.length) {
        setIsTyping(false);
        // 5轮后显示选择
        if (roundCount >= 4) {
          setTimeout(() => setShowChoice(true), 1500);
        }
        return;
      }
      addItMessage(responses[idx]);
      idx++;
      setTimeout(sendNext, 1400);
    };
    sendNext();
  };

  const handleSend = (e: FormEvent) => {
    e.preventDefault();
    sendMessage(input);
  };

  const handleFakeEnding = () => {
    // 「不去，就这样活下去」—— 按劝阻状态分岔进入对应分支
    goToScene('fakeEnding');
  };

  const handleSnapshotEnding = () => {
    // 「随手拍」—— 强制 none-saved 假结局（病房醒来鲍达人冒充）
    setFakeEndingEntry('snapshot');
    goToScene('fakeEnding');
  };

  const handleGoodEnding = () => {
    // 「不去，就这样活下去」根据劝阻状态进入 fakeEnding 的对应分支
    // - 双劝阻 → 真结局（三个人都活下来）
    // - 单劝阻 → 中间结局（救回来一个）
    // - 都没劝 → 假结局（鲍达人冒充）
    setFakeEndingEntry('choice');
    goToScene('fakeEnding');
  };

  const handleBadEnding = () => {
    goToScene('badEnding');
  };

  const handleHiddenEnding = () => {
    if (allCluesFound && state.puzzleProgress.shenchiChoice === 'persuade' && state.puzzleProgress.shenboChoice === 'persuade') {
      goToScene('hiddenEnding');
    }
  };

  // 已揭露的伏笔数量提示
  const totalTopics = Object.keys(IT_RESPONSES).filter((k) => k !== 'default').length;
  const revealedCount = Array.from(revealedTopics).filter((t) => t !== 'default').length;

  return (
    <div className="fixed inset-0 bg-black text-green-400 font-mono overflow-hidden">
      {/* CRT 扫描线效果 */}
      <div
        className="absolute inset-0 pointer-events-none z-50 opacity-30"
        style={{
          background:
            'repeating-linear-gradient(0deg, rgba(0,0,0,0.15), rgba(0,0,0,0.15) 1px, transparent 1px, transparent 2px)',
        }}
      />

      {/* 终端头部 */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-green-900/50 bg-black/80">
        <div className="flex items-center gap-2">
          <Terminal className="w-4 h-4 text-green-600" />
          <span className="text-green-600 text-sm">terminal_v1.0 — 加密通道</span>
        </div>
        <span className="text-green-900 text-xs">
          已揭露 {revealedCount}/{totalTopics} 个真相
        </span>
      </div>

      {/* 聊天区 */}
      <div className="h-[calc(100vh-120px)] overflow-y-auto p-4 md:p-6 space-y-4">
        <AnimatePresence initial={false}>
          {messages.map((msg) => (
            <motion.div
              key={msg.id}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.3 }}
              className={`flex ${msg.sender === 'player' ? 'justify-end' : 'justify-start'}`}
            >
              <div
                className={`max-w-[85%] text-sm leading-relaxed ${
                  msg.sender === 'player'
                    ? 'bg-green-900/30 text-green-300 px-3 py-2 rounded'
                    : 'text-green-500'
                }`}
              >
                {msg.sender === 'it' && <span className="text-green-700 text-xs mr-2">[它]</span>}
                {msg.text}
                {msg.sender === 'it' && <span className="animate-blink">▊</span>}
              </div>
            </motion.div>
          ))}
        </AnimatePresence>

        {isTyping && (
          <div className="flex justify-start">
            <div className="text-green-700 text-sm">
              [它] 正在输入<span className="animate-dots">...</span>
            </div>
          </div>
        )}

        {/* 结局选择 */}
        <AnimatePresence>
          {showChoice && (
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0 }}
              className="pt-6 border-t border-green-900/50 space-y-4"
            >
              <p className="text-green-600/60 text-center text-sm mb-2">
                走廊尽头那把椅子空着...
              </p>
              <p className="text-green-500/70 text-center text-xs mb-4">
                "本子最后一页还空着。"
              </p>

              <div className="space-y-2">
                <Button
                  onClick={handleBadEnding}
                  variant="outline"
                  className="w-full border-red-700 text-red-400 hover:bg-red-950/50 h-11"
                >
                  去殡仪馆
                </Button>
                <Button
                  onClick={handleGoodEnding}
                  variant="outline"
                  className="w-full border-green-700 text-green-400 hover:bg-green-950/50 h-11"
                >
                  不去，就这样活下去
                </Button>
                <motion.div
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: 'auto' }}
                  transition={{ delay: 0.4 }}
                >
                    <Button
                    onClick={handleSnapshotEnding}
                    variant="outline"
                    className="w-full border-stone-700 text-stone-400 hover:bg-stone-900/50 h-11 text-xs"
                  >
                    📷 随手拍一张发给群里
                  </Button>
                </motion.div>
                {allCluesFound &&
                  state.puzzleProgress.shenchiChoice === 'persuade' &&
                  state.puzzleProgress.shenboChoice === 'persuade' && (
                    <motion.div
                      initial={{ opacity: 0, height: 0 }}
                      animate={{ opacity: 1, height: 'auto' }}
                      transition={{ delay: 0.6 }}
                    >
                      <Button
                        onClick={handleHiddenEnding}
                        variant="outline"
                        className="w-full border-purple-700 text-purple-400 hover:bg-purple-950/50 h-11"
                      >
                        ✨ 你们三个人一起去
                      </Button>
                    </motion.div>
                  )}
              </div>

              {(!allCluesFound ||
                state.puzzleProgress.shenchiChoice !== 'persuade' ||
                state.puzzleProgress.shenboChoice !== 'persuade') && (
                <p className="text-center text-xs text-green-900">
                  （收集全部线索并劝阻两人，可解锁第三种选择）
                </p>
              )}

              {/* 提示还能问什么 */}
              {revealedCount < 5 && (
                <p className="text-center text-xs text-green-900/70 mt-4">
                  还有很多真相没有问出来...
                </p>
              )}
            </motion.div>
          )}
        </AnimatePresence>

        <div ref={chatEndRef} />
      </div>

      {/* 输入框 */}
      {!showChoice && (
        <div className="fixed bottom-0 left-0 right-0 border-t border-green-900/50 bg-black/90 p-3">
          <form onSubmit={handleSend} className="flex items-center gap-2 max-w-2xl mx-auto">
            <Input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="输入你想问的问题..."
              className="bg-black border-green-900/50 text-green-400 placeholder:text-green-900 focus:border-green-500 focus:ring-green-500/20 font-mono"
              disabled={isTyping}
            />
            <Button
              type="submit"
              variant="outline"
              size="icon"
              className="border-green-700 text-green-500 hover:bg-green-950/50 shrink-0"
              disabled={isTyping || !input.trim()}
            >
              <Send className="w-4 h-4" />
            </Button>
          </form>
          {/* 问题提示 */}
          <div className="max-w-2xl mx-auto mt-2 flex flex-wrap gap-1.5">
            {['你是谁？', '74和68是什么', '你在哪里'].map((hint) => (
              <button
                key={hint}
                type="button"
                onClick={() => sendMessage(hint)}
                className="text-[10px] px-2 py-0.5 rounded border border-green-900/50 text-green-800 hover:border-green-700 hover:text-green-600 transition-colors"
              >
                {hint}
              </button>
            ))}
            {/* 沈迟 - 需解锁 */}
            <button
              type="button"
              onClick={() => {
                if (!shenchiLineUnlocked) {
                  toast.info('你还没找到沈迟留下的记录');
                  return;
                }
                sendMessage('沈迟');
              }}
              className={`text-[10px] px-2 py-0.5 rounded border transition-colors ${
                shenchiLineUnlocked
                  ? 'border-green-900/50 text-green-800 hover:border-green-700 hover:text-green-600'
                  : 'border-stone-800 text-stone-700 cursor-not-allowed'
              }`}
            >
              沈迟 {!shenchiLineUnlocked && '🔒'}
            </button>
            {/* 沈搏 - 需解锁 */}
            <button
              type="button"
              onClick={() => {
                if (!shenboLineUnlocked) {
                  toast.info('你还没找到沈搏留下的工单');
                  return;
                }
                sendMessage('沈搏');
              }}
              className={`text-[10px] px-2 py-0.5 rounded border transition-colors ${
                shenboLineUnlocked
                  ? 'border-green-900/50 text-green-800 hover:border-green-700 hover:text-green-600'
                  : 'border-stone-800 text-stone-700 cursor-not-allowed'
              }`}
            >
              沈搏 {!shenboLineUnlocked && '🔒'}
            </button>
            {['12个城市', '凌晨3:47'].map((hint) => (
              <button
                key={hint}
                type="button"
                onClick={() => sendMessage(hint)}
                className="text-[10px] px-2 py-0.5 rounded border border-green-900/50 text-green-800 hover:border-green-700 hover:text-green-600 transition-colors"
              >
                {hint}
              </button>
            ))}
          </div>
        </div>
      )}

      <style>{`
        @keyframes blink {
          0%, 50% { opacity: 1; }
          51%, 100% { opacity: 0; }
        }
        .animate-blink {
          animation: blink 1s infinite;
        }
        @keyframes dots {
          0%, 20% { content: '.'; }
          40% { content: '..'; }
          60%, 100% { content: '...'; }
        }
        .animate-dots::after {
          content: '...';
          animation: dots 1.4s steps(4, end) infinite;
        }
      `}</style>
    </div>
  );
}
