import { useState } from 'react';
import { useGame } from '../GameContext';
import { motion, AnimatePresence } from 'framer-motion';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Textarea } from '@/components/ui/textarea';
import { Wrench, Send, AlertTriangle } from 'lucide-react';
import { toast } from 'sonner';
import SceneChrome from '../components/SceneChrome';

const shenboPosts = [
  {
    id: '1',
    date: '2026-02-28',
    content: '今天修了第三台仪器了。\n每台修好之后都会自动录制68秒的音频。\n厂家说这是正常现象，是设备自检。\n但那声音...不像自检。像是什么东西在呼吸。',
  },
  {
    id: '2',
    date: '2026-03-08',
    content: '出差到成都。\n春熙路那栋写字楼的27层，一整层都是医疗设备。\n我在走廊里听到了心跳声，不是从仪器里发出来的。\n是从地板下面。',
  },
  {
    id: '3',
    date: '2026-03-18',
    content: '我在仪器的维护日志里发现了一个词：YQSM。\n查了半天，意思是"仪器声明"。\n声明什么？声明它的存在吗？\n十八层的人说我修的每一台设备，都是"它"的耳朵。',
  },
];

export default function ShenboViewScene() {
  const { goToScene, setPuzzleDone, setVisitorIdentity } = useGame();
  const [activeTab, setActiveTab] = useState<'posts' | 'message'>('posts');
  const [message, setMessage] = useState('');
  const [messageSent, setMessageSent] = useState(false);

  const handleSendMessage = () => {
    if (!message.trim()) return;
    setMessageSent(true);
    setPuzzleDone('shenboWarned');
    toast.success('留言已发送，沈搏看到了你的消息');
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-blue-950/30 to-black text-blue-200">
      <SceneChrome title="沈搏 · 视角" variant="dark" />

      <div className="pt-16 pb-8 px-3 md:px-6 max-w-2xl mx-auto">
        {/* 人物卡片 */}
        <motion.div
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          className="text-center py-6 mb-4"
        >
          <div className="w-16 h-16 mx-auto mb-3 rounded-full bg-blue-900/50 flex items-center justify-center border-2 border-blue-700/50">
            <Wrench className="w-8 h-8 text-blue-500" />
          </div>
          <h1 className="text-xl font-bold text-blue-300">engineer_68</h1>
          <p className="text-blue-700 text-sm">沈搏 · 35岁 · 维修工程师</p>
        </motion.div>

        {/* Tab */}
        <div className="flex items-center gap-1 mb-6 border-b border-blue-900/30">
          <button
            onClick={() => setActiveTab('posts')}
            className={`flex-1 py-2 text-sm border-b-2 transition-colors ${
              activeTab === 'posts'
                ? 'border-blue-500 text-blue-400'
                : 'border-transparent text-blue-700 hover:text-blue-500'
            }`}
          >
            探索记录
          </button>
          <button
            onClick={() => setActiveTab('message')}
            className={`flex-1 py-2 text-sm border-b-2 transition-colors ${
              activeTab === 'message'
                ? 'border-blue-500 text-blue-400'
                : 'border-transparent text-blue-700 hover:text-blue-500'
            }`}
          >
            留言劝阻
          </button>
        </div>

        <AnimatePresence mode="wait">
          {activeTab === 'posts' && (
            <motion.div
              key="posts"
              initial={{ opacity: 0, x: -10 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: -10 }}
              className="space-y-4"
            >
              {shenboPosts.map((post, i) => (
                <motion.div
                  key={post.id}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: i * 0.1 }}
                >
                  <Card className="bg-black/50 border-blue-900/30">
                    <CardContent className="p-4">
                      <div className="flex items-start gap-3 mb-3">
                        <div className="w-8 h-8 rounded-full bg-blue-900/50 flex items-center justify-center flex-shrink-0">
                          <Wrench className="w-4 h-4 text-blue-500" />
                        </div>
                        <div>
                          <p className="text-blue-300 text-sm font-medium">engineer_68</p>
                          <p className="text-blue-800 text-xs">{post.date}</p>
                        </div>
                      </div>
                      <p className="text-blue-200/80 text-sm leading-relaxed whitespace-pre-line">
                        {post.content}
                      </p>
                    </CardContent>
                  </Card>
                </motion.div>
              ))}
            </motion.div>
          )}

          {activeTab === 'message' && (
            <motion.div
              key="message"
              initial={{ opacity: 0, x: 10 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 10 }}
              className="space-y-4"
            >
              <Card className="bg-amber-950/30 border-amber-800/30">
                <CardContent className="p-4">
                  <div className="flex items-start gap-3">
                    <AlertTriangle className="w-5 h-5 text-amber-500 flex-shrink-0 mt-0.5" />
                    <div>
                      <p className="text-amber-300 text-sm font-medium mb-1">
                        你可以留言劝阻沈搏
                      </p>
                      <p className="text-amber-600/70 text-xs">
                        告诉他真相，也许能改变他的命运...
                      </p>
                    </div>
                  </div>
                </CardContent>
              </Card>

              {!messageSent ? (
                <div className="space-y-3">
                  <Textarea
                    value={message}
                    onChange={(e) => setMessage(e.target.value)}
                    placeholder="给沈搏留言..."
                    className="bg-black/50 border-blue-900/30 text-blue-200 placeholder:text-blue-900/60 min-h-[120px] resize-none"
                  />
                  <Button
                    onClick={handleSendMessage}
                    className="w-full bg-blue-600/80 hover:bg-blue-600 text-white border border-blue-500/50 h-11"
                  >
                    <Send className="w-4 h-4 mr-2" />
                    发送留言
                  </Button>
                </div>
              ) : (
                <motion.div
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="space-y-4"
                >
                  {/* 发送的消息 */}
                  <div className="flex justify-end">
                    <div className="bg-blue-900/50 text-blue-200 px-4 py-3 rounded-lg max-w-[80%] text-sm">
                      {message}
                    </div>
                  </div>

                  {/* 沈搏的回复 */}
                  <motion.div
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: 0.8 }}
                    className="flex justify-start"
                  >
                    <div className="bg-black/70 text-blue-300 px-4 py-3 rounded-lg max-w-[80%] text-sm border border-blue-900/30">
                      <p className="text-xs text-blue-600 mb-1">engineer_68 回复：</p>
                      <p>你是谁？你怎么知道这些的？</p>
                      <p className="mt-2">...算了，不管你是谁，谢谢你的提醒。</p>
                      <p className="mt-2">我干这行十几年了，有些事我自己也感觉不对劲。</p>
                      <p className="mt-2">下一个工单...我会再想想的。</p>
                      <p className="text-blue-700 text-xs mt-3">
                        —— 他似乎半信半疑，但决定小心行事
                      </p>
                    </div>
                  </motion.div>
                </motion.div>
              )}
            </motion.div>
          )}
        </AnimatePresence>

        {/* 返回 */}
        <div className="mt-8 pt-4 border-t border-blue-900/20">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => {
              setVisitorIdentity('shenbo');
              goToScene('shibacengForum');
            }}
            className="w-full text-blue-700 hover:text-blue-500 hover:bg-blue-950/30"
          >
            返回十八层论坛
          </Button>
        </div>
      </div>
    </div>
  );
}
