import { Component, ReactNode } from 'react';
import { logger } from '@lark-apaas/client-toolkit-lite';

interface GameErrorBoundaryProps {
  children: ReactNode;
  onReset: () => void;
}

interface GameErrorBoundaryState {
  hasError: boolean;
}

export default class GameErrorBoundary extends Component<
  GameErrorBoundaryProps,
  GameErrorBoundaryState
> {
  constructor(props: GameErrorBoundaryProps) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError(): GameErrorBoundaryState {
    return { hasError: true };
  }

  componentDidCatch(error: unknown) {
    logger.error('Game scene error:', String(error));
  }

  componentDidUpdate(prevProps: GameErrorBoundaryProps) {
    // 如果已经从错误状态恢复，重置标志
    if (this.state.hasError && prevProps !== this.props) {
      this.setState({ hasError: false });
    }
  }

  handleReset = () => {
    this.setState({ hasError: false });
    this.props.onReset();
  };

  render() {
    if (this.state.hasError) {
      // 出错时显示黑屏 + 点击重新开始，直接对接到开场风格
      return (
        <div
          className="fixed inset-0 bg-black flex flex-col items-center justify-center z-[9999] cursor-pointer select-none"
          onClick={this.handleReset}
        >
          <p className="text-white/60 text-sm mb-6">页面加载出错</p>
          <p className="text-white/90 text-lg font-medium mb-4">
            点击任意位置重新开始
          </p>
          <p className="text-white/30 text-xs">本故事纯属虚构，如有雷同纯属巧合</p>
        </div>
      );
    }
    return this.props.children;
  }
}
