import { useGame } from '../GameContext';
import { LogOut } from 'lucide-react';

interface OasTopNavProps {
  activeTab: 'dashboard' | 'archives' | 'allocation' | 'followup' | 'alerts';
}

const NAV_TABS: Array<{ id: string; label: string }> = [
  { id: 'dashboard', label: '工作台' },
  { id: 'archives', label: '档案管理' },
  { id: 'allocation', label: '分配记录' },
  { id: 'followup', label: '随访管理' },
  { id: 'alerts', label: '预警中心' },
];

const SCENE_MAP: Record<string, string> = {
  dashboard: 'oasDashboard',
  archives: 'oasArchives',
  allocation: 'oasAllocation',
  followup: 'oasFollowup',
  alerts: 'oasAlerts',
};

export default function OasTopNav({ activeTab }: OasTopNavProps) {
  const { goToScene, resetGame } = useGame();

  const handleTabClick = (tabId: string) => {
    const sceneId = SCENE_MAP[tabId];
    if (sceneId) {
      goToScene(sceneId as any);
    }
  };

  return (
    <div className="pt-12 bg-[#1e5b9d] border-b border-[#154a82]">
      <div className="max-w-6xl mx-auto px-4 flex items-center gap-0 md:gap-6 text-sm text-blue-200 overflow-x-auto">
        {NAV_TABS.map((tab) => (
          <button
            key={tab.id}
            onClick={() => handleTabClick(tab.id)}
            className={`py-2.5 px-3 whitespace-nowrap transition-colors ${
              activeTab === tab.id
                ? 'text-white border-b-2 border-white font-medium'
                : 'hover:text-white'
            }`}
          >
            {tab.label}
          </button>
        ))}
        <div className="ml-auto flex items-center gap-3 flex-shrink-0 ml-2">
          <span className="text-xs hidden md:inline">程未 · 器官协调员</span>
          <button
            onClick={resetGame}
            className="text-xs text-blue-200 hover:text-white flex items-center gap-1"
          >
            <LogOut className="w-3 h-3" />
            退出
          </button>
        </div>
      </div>
    </div>
  );
}
