import { useState } from 'react';
import { useGame } from '../GameContext';
import { motion, AnimatePresence } from 'framer-motion';
import { MOCK_STORY } from '@/data/story';
import {
  Building2,
  ArrowLeft,
  User,
  Bell,
  FileText,
  Mail,
  Calendar,
  ChevronRight,
  X,
  AlertTriangle,
  Briefcase,
} from 'lucide-react';

export default function PanyangStaffHomeScene() {
  const { goBack, state } = useGame();
  const { panyangStaff } = MOCK_STORY;
  const [activeTab, setActiveTab] = useState<'announcement' | 'work' | 'email'>('announcement');
  const [selectedMail, setSelectedMail] = useState<string | null>(null);

  const { employee, announcements, workRecords, internalEmails } = panyangStaff;

  const selectedEmail = internalEmails.find((m) => m.id === selectedMail) || null;

  return (
    <div className="min-h-screen bg-slate-50">
      {/* 顶栏 */}
      <div className="bg-white border-b border-slate-200 sticky top-0 z-30">
        <div className="max-w-6xl mx-auto px-4 h-14 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <button
              onClick={goBack}
              className="flex items-center gap-1 text-sm text-gray-600 hover:text-blue-700 transition-colors"
            >
              <ArrowLeft className="w-4 h-4" />
            </button>
            <div className="w-7 h-7 bg-blue-700/10 rounded-full flex items-center justify-center">
              <Building2 className="w-4 h-4 text-blue-700" />
            </div>
            <div>
              <h1 className="text-sm font-medium text-slate-800 leading-tight">员工工作台</h1>
              <p className="text-[11px] text-gray-500 leading-tight">盘阳生物科技 · 设备工程部</p>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <button className="p-1.5 text-gray-500 hover:text-blue-700 hover:bg-slate-100 rounded-full relative">
              <Bell className="w-4 h-4" />
              <span className="absolute top-1 right-1 w-1.5 h-1.5 bg-red-500 rounded-full" />
            </button>
            <div className="flex items-center gap-2">
              <div className="w-7 h-7 bg-blue-700 rounded-full flex items-center justify-center text-white text-xs font-medium">
                沈
              </div>
              <div className="hidden md:block">
                <p className="text-xs text-slate-700 leading-tight">{employee.name}</p>
                <p className="text-[10px] text-gray-500 leading-tight">{employee.employeeId}</p>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4 py-5">
        {/* 员工信息卡 */}
        <motion.div
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          className="bg-gradient-to-r from-blue-700 to-blue-900 text-white rounded-lg p-5 mb-5"
        >
          <div className="flex items-start justify-between">
            <div>
              <p className="text-xs text-blue-200">欢迎回来</p>
              <h2 className="text-xl font-medium mt-1">{employee.name}</h2>
              <p className="text-sm text-blue-200 mt-0.5">{employee.position} · {employee.department}</p>
            </div>
            <div className="text-right">
              <p className="text-[11px] text-blue-300">员工号</p>
              <p className="text-sm font-mono mt-0.5">{employee.employeeId}</p>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4 mt-4 pt-4 border-t border-blue-500/30">
            <div>
              <p className="text-[11px] text-blue-300">入职日期</p>
              <p className="text-sm mt-0.5">{employee.hireDate}</p>
            </div>
            <div>
              <p className="text-[11px] text-blue-300">直属上级</p>
              <p className="text-sm mt-0.5">{employee.manager}</p>
            </div>
          </div>
          <div className="mt-3 pt-3 border-t border-blue-500/20">
            <p className="text-[11px] text-blue-300 mb-1">负责范围</p>
            <p className="text-xs text-blue-100 leading-relaxed">{employee.responsibilities}</p>
          </div>
          <div className="mt-3 pt-3 border-t border-blue-500/20">
            <p className="text-[11px] text-blue-300 mb-1">推荐人</p>
            <p className="text-xs text-blue-200/70 italic">{employee.recommendBy}</p>
          </div>
        </motion.div>

        {/* Tab 切换 */}
        <div className="bg-white border border-slate-200 mb-4">
          <div className="flex border-b border-slate-200">
            {[
              { key: 'announcement', label: '内部公告', icon: Bell },
              { key: 'work', label: '工作记录', icon: FileText },
              { key: 'email', label: '内部邮件', icon: Mail },
            ].map((t) => (
              <button
                key={t.key}
                onClick={() => setActiveTab(t.key as typeof activeTab)}
                className={`flex-1 h-10 text-xs flex items-center justify-center gap-1.5 border-b-2 transition-colors ${
                  activeTab === t.key
                    ? 'text-blue-700 border-blue-700 bg-blue-50/30'
                    : 'text-gray-500 border-transparent hover:text-gray-700 hover:bg-slate-50'
                }`}
              >
                <t.icon className="w-3.5 h-3.5" />
                {t.label}
                {t.key === 'email' && internalEmails.filter((e) => !e.isRead).length > 0 && (
                  <span className="w-1.5 h-1.5 bg-red-500 rounded-full" />
                )}
              </button>
            ))}
          </div>

          {/* 公告列表 */}
          {activeTab === 'announcement' && (
            <div className="divide-y divide-slate-100">
              {announcements.map((ann, i) => (
                <motion.div
                  key={ann.id}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ delay: i * 0.05 }}
                  className="p-4 hover:bg-blue-50/20 cursor-pointer transition-colors"
                >
                  <div className="flex items-start gap-3">
                    <div className="w-8 h-8 bg-red-50 rounded flex items-center justify-center flex-shrink-0 mt-0.5">
                      <AlertTriangle className="w-4 h-4 text-red-500" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span className="text-[10px] px-1.5 py-0.5 bg-red-100 text-red-600 rounded">重要</span>
                        <span className="text-[11px] text-gray-400">{ann.date}</span>
                      </div>
                      <h3 className="text-sm font-medium text-slate-800 mt-1.5">{ann.title}</h3>
                      <p className="text-xs text-gray-500 mt-1 line-clamp-2">
                        {ann.content.replace(/\\n/g, ' ')}
                      </p>
                      <p className="text-[11px] text-gray-400 mt-2">
                        发件人：{ann.sender}
                      </p>
                    </div>
                    <ChevronRight className="w-4 h-4 text-gray-300 flex-shrink-0 mt-2" />
                  </div>
                </motion.div>
              ))}
            </div>
          )}

          {/* 工作记录 */}
          {activeTab === 'work' && (
            <div className="divide-y divide-slate-100">
              {workRecords.map((rec, i) => (
                <motion.div
                  key={i}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ delay: i * 0.05 }}
                  className="p-4"
                >
                  <div className="flex items-start gap-3">
                    <div className="w-8 h-8 bg-blue-50 rounded flex items-center justify-center flex-shrink-0 mt-0.5">
                      <Briefcase className="w-4 h-4 text-blue-600" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <Calendar className="w-3 h-3 text-gray-400" />
                        <span className="text-[11px] text-gray-500">{rec.date}</span>
                      </div>
                      <p className="text-sm text-slate-700 mt-1.5 leading-relaxed">{rec.content}</p>
                    </div>
                  </div>
                </motion.div>
              ))}
            </div>
          )}

          {/* 内部邮件 */}
          {activeTab === 'email' && (
            <div className="divide-y divide-slate-100">
              {internalEmails.map((mail, i) => (
                <motion.div
                  key={mail.id}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ delay: i * 0.05 }}
                  onClick={() => setSelectedMail(mail.id)}
                  className={`p-4 hover:bg-blue-50/20 cursor-pointer transition-colors ${
                    !mail.isRead ? 'bg-blue-50/10' : ''
                  }`}
                >
                  <div className="flex items-start gap-3">
                    {!mail.isRead && (
                      <span className="w-2 h-2 bg-blue-600 rounded-full mt-2 flex-shrink-0" />
                    )}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center justify-between gap-2">
                        <span className="text-sm font-medium text-slate-800 truncate">{mail.subject}</span>
                        <span className="text-[11px] text-gray-400 flex-shrink-0">{mail.date}</span>
                      </div>
                      <p className="text-xs text-gray-600 mt-1 truncate">{mail.from}</p>
                      <p className="text-xs text-gray-400 mt-1 line-clamp-1">
                        {mail.content.replace(/\\n/g, ' ')}
                      </p>
                    </div>
                    <ChevronRight className="w-4 h-4 text-gray-300 flex-shrink-0 mt-2" />
                  </div>
                </motion.div>
              ))}
            </div>
          )}
        </div>

        {/* 快捷入口 */}
        <div className="grid grid-cols-3 gap-3">
          {[
            { label: '日程', icon: Calendar },
            { label: '请假', icon: User },
            { label: '报销', icon: FileText },
          ].map((q) => (
            <div
              key={q.label}
              className="bg-white border border-slate-200 py-4 flex flex-col items-center gap-1.5 cursor-not-allowed opacity-60"
            >
              <q.icon className="w-5 h-5 text-gray-400" />
              <span className="text-xs text-gray-500">{q.label}</span>
            </div>
          ))}
        </div>
      </div>

      {/* 邮件详情抽屉 */}
      <AnimatePresence>
        {selectedEmail && (
          <>
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              onClick={() => setSelectedMail(null)}
              className="fixed inset-0 bg-black/40 z-40"
            />
            <motion.div
              initial={{ x: '100%' }}
              animate={{ x: 0 }}
              exit={{ x: '100%' }}
              transition={{ type: 'spring', damping: 25, stiffness: 200 }}
              className="fixed top-0 right-0 h-full w-full max-w-lg bg-white z-50 shadow-xl overflow-y-auto"
            >
              <div className="sticky top-0 bg-white border-b border-gray-200 px-4 py-3 flex items-center justify-between z-10">
                <h3 className="text-sm font-medium text-gray-800">{selectedEmail.subject}</h3>
                <button
                  onClick={() => setSelectedMail(null)}
                  className="p-1.5 text-gray-500 hover:text-gray-700 hover:bg-gray-100 rounded"
                >
                  <X className="w-5 h-5" />
                </button>
              </div>

              <div className="p-4">
                <div className="flex items-start gap-3 pb-4 border-b border-gray-100">
                  <div className="w-9 h-9 bg-blue-100 rounded-full flex items-center justify-center text-blue-700 text-xs font-medium flex-shrink-0">
                    {selectedEmail.from.charAt(0)}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm text-slate-800 font-medium truncate">{selectedEmail.from}</p>
                    <p className="text-[11px] text-gray-500 mt-0.5">
                      致：{selectedEmail.to}
                    </p>
                    <p className="text-[11px] text-gray-400 mt-0.5">{selectedEmail.date}</p>
                  </div>
                </div>

                <div className="pt-4">
                  <p className="text-sm text-gray-700 leading-relaxed whitespace-pre-line">
                    {selectedEmail.content.replace(/\\n/g, '\n')}
                  </p>
                </div>
              </div>
            </motion.div>
          </>
        )}
      </AnimatePresence>
    </div>
  );
}
