import { useState, useEffect } from 'react';
import { useGame } from '../GameContext';
import { motion, AnimatePresence } from 'framer-motion';
import { Button } from '@/components/ui/button';
import { RotateCcw, Sun } from 'lucide-react';
import { MOCK_STORY } from '@/data/story';
import { scopedStorage } from '@lark-apaas/client-toolkit-lite';
import FourthWallEnding from '../components/FourthWallEnding';
import FinalEpilogue from '../components/FinalEpilogue';

export default function GoodEndingScene() {
  const { resetGame } = useGame();
  const { endings } = MOCK_STORY;
  const [stage, setStage] = useState(0);
  const [showEpilogue, setShowEpilogue] = useState(false);
  const [showFourthWall, setShowFourthWall] = useState(false);

  useEffect(() => {
    // 标记游戏已通关（用于二周目身份识别）
    scopedStorage.setItem('gameCompleted', '1');
    try {
      localStorage.setItem('molan_has_completed', 'true');
    } catch {
      // ignore
    }
  }, []);

  useEffect(() => {
    const timers = [
      setTimeout(() => setStage(1), 1200),   // 程未没有去
      setTimeout(() => setStage(2), 4500),   // 辞掉工作，搬去另一个城市
      setTimeout(() => setStage(3), 8500),   // 半年后回西安办事，去医院看老同事
      setTimeout(() => setStage(4), 13500),  // 走廊里看见了三个人
      setTimeout(() => setStage(5), 20000),  // 计划取消·真结局旁白
      setTimeout(() => setStage(6), 29000),  // 余韵·反转疑问
    ];
    return () => timers.forEach(clearTimeout);
  }, []);

  // 剧情结束后，先播放统一收尾旁白，再进入第四面墙片尾
  useEffect(() => {
    const timer = setTimeout(() => setShowEpilogue(true), 34000);
    return () => clearTimeout(timer);
  }, []);

  return (
    <div className="fixed inset-0 bg-gradient-to-b from-slate-50 to-white overflow-hidden flex items-center justify-center">
      <AnimatePresence mode="wait">
        {stage === 0 && (
          <motion.div
            key="s0"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="text-center"
          >
            <p className="text-slate-600 text-lg">程未没有去...</p>
          </motion.div>
        )}

        {stage === 1 && (
          <motion.div
            key="s1"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 1 }}
            className="text-center px-6"
          >
            <Sun className="w-16 h-16 text-amber-400 mx-auto mb-6" />
            <h1 className="text-2xl md:text-3xl font-bold text-slate-700 mb-4">
              {endings.good.title}
            </h1>
            <p className="text-slate-500 max-w-md mx-auto leading-relaxed">
              {endings.good.text}
            </p>
          </motion.div>
        )}

        {stage === 2 && (
          <motion.div
            key="s2"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 1 }}
            className="text-center px-6 space-y-4"
          >
            <div className="space-y-3 max-w-md mx-auto">
              <p className="text-slate-600 text-sm">
                他辞掉了OAS的工作，搬到了一个安静的城市。
              </p>
              <p className="text-slate-600 text-sm">
                十八层的论坛他再也没登过。临渊的收藏夹也删了。
              </p>
              <p className="text-slate-600 text-sm">
                沈迟的术后恢复很好，偶尔还会跟程未通电话，说最近又能跑三公里了。
              </p>
              <p className="text-slate-600 text-sm">
                沈搏去了一家小公司，修普通的医疗设备，不再碰监护仪，也不再出差到深夜。
              </p>
              <p className="text-slate-600 text-sm">
                三个人都好好地活着。
              </p>
              <p className="text-slate-400 text-xs mt-4">
                好像什么都没有发生过一样。
              </p>
            </div>
          </motion.div>
        )}

        {stage === 3 && (
          <motion.div
            key="s3"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 1 }}
            className="text-center px-6 space-y-3"
          >
            <p className="text-slate-500 text-sm">半年后，程未回西安办事。</p>
            <p className="text-slate-500 text-sm">顺路去以前常去的那家医院看老同事。</p>
            <p className="text-slate-400 text-sm">他走在三楼东走廊上。</p>
          </motion.div>
        )}

        {stage === 4 && (
          <motion.div
            key="s4"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 1.2 }}
            className="text-center px-6 space-y-4 max-w-lg mx-auto"
          >
            <p className="text-slate-500 text-sm">走廊里有三个人。</p>

            {/* 走廊场景极简示意 */}
            <div className="relative h-40 bg-slate-100/50 rounded-lg border border-slate-200 overflow-hidden my-4">
              {/* 地砖线 */}
              <div className="absolute bottom-0 left-0 right-0 h-20 bg-gradient-to-t from-slate-200/60 to-transparent" />
              <div className="absolute bottom-4 left-0 right-0 flex justify-around px-8">
                {Array.from({ length: 6 }).map((_, i) => (
                  <div key={i} className="w-16 h-px bg-slate-300/50" />
                ))}
              </div>

              {/* 沈迟——刚做完复查出来，年轻 */}
              <motion.div
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: 0.3 }}
                className="absolute bottom-6 left-[18%] text-center"
              >
                <div className="w-8 h-12 mx-auto bg-blue-200/70 rounded-t-full" />
                <p className="text-[10px] text-slate-500 mt-1">沈迟</p>
              </motion.div>

              {/* 沈搏——背着工具包，站着看设备 */}
              <motion.div
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: 0.6 }}
                className="absolute bottom-6 right-[22%] text-center"
              >
                <div className="w-9 h-14 mx-auto bg-stone-300/70 rounded-t-sm" />
                <p className="text-[10px] text-slate-500 mt-1">沈搏</p>
              </motion.div>

              {/* 走廊尽头的老太太——坐在绿椅子上 */}
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 1 }}
                className="absolute bottom-4 left-1/2 -translate-x-1/2 text-center"
              >
                <div className="w-10 h-3 bg-emerald-600/60 rounded-sm mx-auto" />
                <div className="w-6 h-8 bg-stone-400/50 mx-auto -mt-0.5 rounded-t-full" />
                <p className="text-[10px] text-stone-500 mt-1">值班的</p>
              </motion.div>

              {/* 中间连线——三人在同一条走廊里 */}
              <motion.div
                initial={{ scaleX: 0 }}
                animate={{ scaleX: 1 }}
                transition={{ delay: 1.4, duration: 0.8 }}
                className="absolute bottom-10 left-[20%] right-[20%] h-px bg-slate-300/60 origin-center"
              />
            </div>

            <p className="text-slate-500 text-sm leading-relaxed">
              一个是刚做完复查的沈迟。<br/>
              一个是刚好来修设备的沈搏。<br/>
              走廊尽头的绿椅子上，坐着那个记本子的老太太。
            </p>
            <p className="text-slate-400 text-sm leading-relaxed">
              三个人在同一条走廊里。<br/>
              隔着十几米的距离。<br/>
              互相不知道对方的存在。
            </p>
            <p className="text-slate-400 text-xs mt-2">
              沈迟看了一眼走廊尽头的老太太，又低下头去看手机。<br/>
              沈搏擦了擦手上的灰，背着工具包往电梯走。<br/>
              老太太在本子上新写了一行，头也没抬。
            </p>
            <p className="text-emerald-600/70 text-xs mt-2 italic">
              没有人打招呼。<br/>
              没有人停下。<br/>
              三个人都好好的。
            </p>
            <p className="text-slate-300 text-[10px] mt-4">
              那天西安下了点小雨。<br/>
              走廊很安静。<br/>
              没有蚊子。
            </p>
          </motion.div>
        )}

        {stage === 5 && (
          <motion.div
            key="s5-break"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 1.5 }}
            className="text-center px-6 space-y-5 max-w-md mx-auto"
          >
            <motion.p
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.3, duration: 1 }}
              className="text-2xl md:text-3xl font-serif text-slate-700 tracking-wider"
            >
              计 划 终 止
            </motion.p>

            <div className="space-y-3 text-left">
              <motion.p
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 1.5, duration: 1 }}
                className="text-slate-600 text-sm leading-relaxed"
              >
                你劝沈迟别停药的那个晚上，他把药吃下去了。
              </motion.p>
              <motion.p
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 2.5, duration: 1 }}
                className="text-slate-600 text-sm leading-relaxed"
              >
                他术后恢复得很好，那颗心脏不需要再被取出来。
              </motion.p>
              <motion.p
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 3.5, duration: 1 }}
                className="text-slate-600 text-sm leading-relaxed"
              >
                你劝沈搏别点开那68秒录音，他母亲的意识没有被拖进来，他收拾工具箱回了老家。
              </motion.p>
              <motion.p
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 5, duration: 1 }}
                className="text-slate-500 text-sm leading-relaxed"
              >
                原本的流程是取出这颗心换下一个人，你改了两个选择，这个计划取消了。
              </motion.p>
              <motion.p
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 6.2, duration: 1 }}
                className="text-slate-500 text-sm leading-relaxed"
              >
                没有人再被当成容器。
              </motion.p>
              <motion.p
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 7.5, duration: 1.5 }}
                className="text-emerald-600 text-base font-medium pt-2 border-t border-slate-200/60"
              >
                这颗心，第一次可以为自己跳。
              </motion.p>
            </div>
          </motion.div>
        )}

        {stage >= 6 && (
          <motion.div
            key="s5"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 1.5 }}
            className="text-center px-6 space-y-8"
          >
            <motion.div
              animate={{ opacity: [0, 1, 0, 1] }}
              transition={{ duration: 4, times: [0, 0.3, 0.7, 1] }}
            >
              <p className="text-red-600 text-lg md:text-xl font-bold">
                {endings.good.twistText}
              </p>
            </motion.div>

             <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 3 }}
              className="space-y-2"
            >
              <p className="text-slate-400 text-xs">
                你确定这是真的吗？
              </p>
              <p className="text-slate-400 text-xs">
                你确定...走廊尽头那把椅子上，她写的最后一行不是「程未」？
              </p>
              <p className="text-slate-500 text-[10px] mt-2">
                你确定她合上本子的时候，没往你这边看一眼？
              </p>
            </motion.div>

            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 5 }}
            >
              <Button
                onClick={resetGame}
                variant="outline"
                className="border-slate-300 text-slate-600 hover:bg-slate-100"
              >
                <RotateCcw className="w-4 h-4 mr-2" />
                再试一次
              </Button>
              <p className="text-slate-300 text-xs mt-4">—— 真结局 · 计划取消 ——</p>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
      <AnimatePresence>
        {showEpilogue && (
          <div className="absolute inset-0 z-40">
            <FinalEpilogue onDone={() => setShowFourthWall(true)} />
          </div>
        )}
      </AnimatePresence>
      <AnimatePresence>
        {showFourthWall && <FourthWallEnding />}
      </AnimatePresence>
    </div>
  );
}
