import { useState, useEffect } from 'react';
import { useGame } from '../GameContext';
import { motion, AnimatePresence } from 'framer-motion';
import { Button } from '@/components/ui/button';
import { RotateCcw, Users, Sparkles, MapPin } from 'lucide-react';
import { MOCK_STORY } from '@/data/story';
import { scopedStorage, logger } from '@lark-apaas/client-toolkit-lite';
import FourthWallEnding from '../components/FourthWallEnding';
import FinalEpilogue from '../components/FinalEpilogue';

export default function HiddenEndingScene() {
  const { resetGame } = useGame();
  const { endings } = MOCK_STORY;
  const [stage, setStage] = useState(0);
  const [showEpilogue, setShowEpilogue] = useState(false);
  const [showFourthWall, setShowFourthWall] = useState(false);
  const [playerCity, setPlayerCity] = useState<string>('你所在的城市');
  const [turnStage, setTurnStage] = useState(0); // 0=正常, 1=转头盯镜头, 2=地址出现, 3=渗血

  useEffect(() => {
    // 标记游戏已通关（用于二周目身份识别）
    scopedStorage.setItem('gameCompleted', '1');
    try {
      localStorage.setItem('molan_has_completed', 'true');
    } catch {
      // ignore
    }
  }, []);

  useEffect(() => {
    const timers = [
      setTimeout(() => setStage(1), 1000),
      setTimeout(() => setStage(2), 4000),
      setTimeout(() => setStage(3), 7000),
      setTimeout(() => setStage(4), 10500),
      setTimeout(() => setStage(5), 14000),
    ];
    return () => timers.forEach(clearTimeout);
  }, []);

  // 尝试获取玩家城市（通过 IP 定位接口兜底，拿不到就留通用文案）
  useEffect(() => {
    async function fetchCity() {
      try {
        // 尝试调用公开 IP 定位接口
        const res = await fetch('https://api.ipapi.is/?ip=').catch(() => null);
        if (res?.ok) {
          const data = await res.json().catch(() => null);
          if (data?.location?.city) {
            setPlayerCity(data.location.city);
          }
        }
      } catch (e) {
        logger.info('city fetch failed:', String(e));
      }
    }
    fetchCity();
  }, []);

  // 三人转头盯镜头 + 渗血 序列（在 stage 2 之后触发）
  useEffect(() => {
    if (stage < 2) return;
    const timers = [
      // 沈搏说话 + 沈迟看表（3:47）
      setTimeout(() => setTurnStage(1), 2000),
      // 三人一起转头
      setTimeout(() => setTurnStage(2), 5500),
      // 盯镜头三秒后地址出现
      setTimeout(() => setTurnStage(3), 9000),
      // 字开始渗血变红
      setTimeout(() => setTurnStage(4), 11500),
    ];
    return () => timers.forEach(clearTimeout);
  }, [stage]);

  // 剧情结束后，先播放统一收尾旁白，再进入第四面墙片尾
  useEffect(() => {
    const timer = setTimeout(() => setShowEpilogue(true), 14000);
    return () => clearTimeout(timer);
  }, []);

  return (
    <div className="fixed inset-0 bg-gradient-to-b from-purple-950 to-black overflow-hidden flex items-center justify-center">
      {/* 星星效果 */}
      <div className="absolute inset-0 overflow-hidden">
        {[...Array(50)].map((_, i) => (
          <motion.div
            key={i}
            className="absolute w-1 h-1 bg-purple-300 rounded-full"
            style={{
              left: `${Math.random() * 100}%`,
              top: `${Math.random() * 100}%`,
            }}
            animate={{
              opacity: [0.2, 1, 0.2],
              scale: [0.5, 1, 0.5],
            }}
            transition={{
              duration: 2 + Math.random() * 3,
              repeat: Infinity,
              delay: Math.random() * 2,
            }}
          />
        ))}
      </div>

      <AnimatePresence mode="wait">
        {stage === 0 && (
          <motion.div
            key="s0"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="text-center"
          >
            <p className="text-purple-300 text-lg">三个人站在殡仪馆门口...</p>
          </motion.div>
        )}

        {stage === 1 && (
          <motion.div
            key="s1"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 1 }}
            className="text-center px-6"
          >
            <Users className="w-16 h-16 text-purple-400 mx-auto mb-6" />
            <h1 className="text-2xl md:text-3xl font-bold text-purple-300 mb-4 tracking-wider">
              {endings.hidden.title}
            </h1>
            <p className="text-purple-400/80 max-w-md mx-auto leading-relaxed">
              {endings.hidden.text}
            </p>
          </motion.div>
        )}

        {stage === 2 && (
          <motion.div
            key="s2"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 1 }}
            className="text-center px-6 space-y-4 max-w-md mx-auto relative"
          >
            {/* 三人站在殡仪馆门口 */}
            <div className="space-y-3">
              <p className="text-purple-300/80 text-sm">
                殡仪馆的铁门虚掩着。
              </p>
              <p className="text-purple-400/60 text-xs">
                门缝里漏出一线昏黄的光。
              </p>
            </div>

            {/* 沈搏说话 */}
            {turnStage >= 1 && turnStage < 2 && (
              <motion.div
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.8 }}
                className="text-left bg-purple-950/30 border border-purple-800/30 rounded-lg p-3 mt-4"
              >
                <p className="text-purple-300/80 text-xs">沈搏搓了搓手：</p>
                <p className="text-purple-200/80 text-sm mt-1">
                  好冷啊，
                  <br />
                  大半夜跑这来干嘛。
                </p>
              </motion.div>
            )}

            {/* 沈迟看表 */}
            {turnStage >= 1 && turnStage < 2 && (
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ delay: 1.5, duration: 1 }}
                className="text-right mt-3"
              >
                <p className="text-purple-400/60 text-xs">沈迟抬起手腕看了一眼——</p>
                <motion.p
                  animate={{ opacity: [0.5, 1, 0.5] }}
                  transition={{ duration: 2, repeat: Infinity }}
                  className="text-purple-300 text-lg font-mono tracking-wider mt-1"
                >
                  03 : 47 : 00
                </motion.p>
                <p className="text-purple-600/60 text-[10px] mt-0.5">秒针停了。</p>
              </motion.div>
            )}

            {/* 三人一起转头盯镜头 */}
            {turnStage >= 2 && (
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ duration: 1.2 }}
                className="absolute inset-0 flex items-center justify-center"
              >
                <div className="text-center space-y-4">
                  <motion.p
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ duration: 0.8 }}
                    className="text-purple-400/50 text-xs"
                  >
                    三个人同时转过了头。
                  </motion.p>

                  {/* 三张脸的剪影盯着你 */}
                  <motion.div
                    initial={{ scale: 0.9, opacity: 0 }}
                    animate={{ scale: 1, opacity: 1 }}
                    transition={{ delay: 0.5, duration: 1 }}
                    className="flex justify-center gap-6 my-6"
                  >
                    {[0, 1, 2].map((i) => (
                      <motion.div
                        key={i}
                        animate={{
                          y: [0, -2, 0],
                        }}
                        transition={{
                          duration: 3,
                          repeat: Infinity,
                          delay: i * 0.3,
                          ease: 'easeInOut',
                        }}
                        className="w-12 h-16 rounded-t-full bg-purple-900/60 border border-purple-700/40 relative overflow-hidden"
                      >
                        {/* 眼睛 */}
                        <div className="absolute top-5 left-2 w-1.5 h-1.5 rounded-full bg-purple-300" />
                        <div className="absolute top-5 right-2 w-1.5 h-1.5 rounded-full bg-purple-300" />
                      </motion.div>
                    ))}
                  </motion.div>

                  <motion.p
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 0.6 }}
                    transition={{ delay: 1.5, duration: 1 }}
                    className="text-purple-500/60 text-[10px] tracking-widest"
                  >
                    他们在看你。
                  </motion.p>
                </div>
              </motion.div>
            )}

            {/* 地址出现 + 渗血变红 */}
            {turnStage >= 3 && (
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 1 }}
                className={`mt-6 text-center space-y-2 transition-colors duration-1000 ${
                  turnStage >= 4 ? 'text-red-500' : 'text-stone-400/70'
                }`}
              >
                <p className="text-[10px] tracking-[0.3em] opacity-60">
                  · 自动获取当前位置 ·
                </p>
                <div className={`inline-block px-4 py-2 border rounded transition-all duration-1000 ${
                  turnStage >= 4
                    ? 'border-red-700/60 bg-red-950/30 text-red-400'
                    : 'border-stone-700/40 bg-stone-900/30 text-stone-400'
                }`}>
                  <div className="flex items-center gap-2 justify-center">
                    <MapPin className={`w-4 h-4 ${turnStage >= 4 ? 'text-red-500' : 'text-stone-500'}`} />
                    <span className="text-sm tracking-wider">
                      {playerCity}市殡仪馆
                    </span>
                  </div>
                </div>

                {turnStage >= 4 && (
                  <motion.p
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ delay: 1, duration: 1.5 }}
                    className="text-red-400/90 text-sm tracking-wider pt-2"
                    style={{ textShadow: '0 0 8px rgba(220,38,38,0.4)' }}
                  >
                    你什么时候来找我？
                  </motion.p>
                )}

                {turnStage >= 4 && (
                  <motion.p
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 0.5 }}
                    transition={{ delay: 2.5, duration: 1.5 }}
                    className="text-red-600/50 text-[10px]"
                  >
                    （血从字的笔画里慢慢渗出来）
                  </motion.p>
                )}
              </motion.div>
            )}
          </motion.div>
        )}

        {stage === 3 && (
          <motion.div
            key="s3"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 1 }}
            className="text-center px-6"
          >
            <motion.div
              animate={{
                scale: [1, 1.2, 1],
                opacity: [0.5, 1, 0.5],
              }}
              transition={{ duration: 3, repeat: Infinity }}
              className="w-24 h-24 mx-auto mb-6"
            >
              <svg viewBox="0 0 100 100" className="w-full h-full">
                <polygon
                  points="50,10 90,80 10,80"
                  fill="none"
                  stroke="#a855f7"
                  strokeWidth="1.5"
                />
                <polygon
                  points="50,90 10,20 90,20"
                  fill="none"
                  stroke="#a855f7"
                  strokeWidth="1.5"
                />
              </svg>
            </motion.div>
            <p className="text-purple-400 text-sm">门内的黑暗没有吞没他们</p>
            <p className="text-purple-400 text-sm mt-2">因为他们一起走了进去</p>
          </motion.div>
        )}

        {stage === 4 && (
          <motion.div
            key="s4"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="text-center px-6"
          >
            <Sparkles className="w-12 h-12 text-amber-400 mx-auto mb-4" />
            <p className="text-amber-300/80 text-sm">
              1974年的秘密，十二座城市的布局，
            </p>
            <p className="text-amber-300/80 text-sm">
              经书里的密文，盘阳生物的阴谋——
            </p>
            <p className="text-amber-300/80 text-sm mt-4">
              这一切，才刚刚开始。
            </p>
          </motion.div>
        )}

        {stage >= 5 && (
          <motion.div
            key="s5"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 1.5 }}
            className="text-center px-6 space-y-8"
          >
            <motion.p
              animate={{ opacity: [0.5, 1, 0.5] }}
              transition={{ duration: 3, repeat: Infinity }}
              className="text-3xl md:text-4xl font-bold text-purple-300 tracking-[0.3em]"
            >
              {endings.hidden.teaser}
            </motion.p>

            <div className="space-y-2">
              <p className="text-purple-600 text-xs">
                恭喜你解锁了隐藏结局
              </p>
              <p className="text-purple-700 text-xs">
                第二部《临渊·二十四城记》敬请期待
              </p>
            </div>

            <Button
              onClick={resetGame}
              variant="outline"
              className="border-purple-700 text-purple-400 hover:bg-purple-950/50"
            >
              <RotateCcw className="w-4 h-4 mr-2" />
              重新探索
            </Button>
          </motion.div>
        )}
      </AnimatePresence>
      <AnimatePresence>
        {showEpilogue && (
          <div className="absolute inset-0 z-40">
            <FinalEpilogue onDone={() => setShowFourthWall(true)} />
          </div>
        )}
      </AnimatePresence>
      <AnimatePresence>
        {showFourthWall && <FourthWallEnding />}
      </AnimatePresence>
    </div>
  );
}
