import { useState, FormEvent } from 'react';
import { useGame, SceneId } from '../GameContext';
import { motion, AnimatePresence } from 'framer-motion';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { AlertCircle, Key, ArrowRight, Lock } from 'lucide-react';
import { toast } from 'sonner';
import { checkAnswer, base64Decode } from '../lib/puzzleUtils';
import SceneChrome from '../components/SceneChrome';

export default function Door1PuzzleScene() {
  const { goToScene, setPuzzleDone } = useGame();
  const [answer, setAnswer] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);
  const [showHint, setShowHint] = useState(false);
  const [showDecode, setShowDecode] = useState(false);
  const [shake, setShake] = useState(false);

  const encodedText = 'NzQzNDc=';
  const correctAnswer = '74347';

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    setError('');

    if (checkAnswer(answer, correctAnswer, true)) {
      setSuccess(true);
      setPuzzleDone('door1Puzzle');
      toast.success('门已打开');

      setTimeout(() => {
        goToScene('huaxiaForum');
      }, 1200);
    } else {
      setError('密码错误');
      setShake(true);
      setTimeout(() => setShake(false), 500);
    }
  };

  return (
    <div className="min-h-screen bg-slate-900">
      <SceneChrome title="门1" variant="dark" />

      <div className="pt-20 pb-8 px-3 md:px-6 max-w-lg mx-auto">
        <AnimatePresence mode="wait">
          {!success ? (
            <motion.div
              key="puzzle"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              transition={{ duration: 0.4 }}
              className="space-y-6"
            >
              {/* 门的视觉 */}
              <div className="relative h-48 flex items-center justify-center">
                <div className="absolute inset-0 flex items-center justify-center">
                  <div className="w-32 h-40 border-2 border-slate-700 rounded-t-full bg-gradient-to-b from-slate-800 to-slate-900 relative">
                    <div className="absolute right-3 top-1/2 w-2 h-2 rounded-full bg-red-500" />
                    <Lock className="absolute left-1/2 -translate-x-1/2 top-1/2 w-8 h-8 text-slate-600" />
                  </div>
                </div>
                <motion.div
                  animate={{ opacity: [0.3, 1, 0.3] }}
                  transition={{ duration: 3, repeat: Infinity }}
                  className="relative z-10 text-center"
                >
                  <p className="text-red-400/60 text-xs tracking-widest">第 一 道 门</p>
                </motion.div>
              </div>

              <Card className={`bg-slate-800/50 border-slate-700 backdrop-blur-sm ${shake ? 'animate-shake' : ''}`}>
                <CardHeader className="pb-3">
                  <div className="flex items-center gap-2">
                    <Key className="w-5 h-5 text-red-500" />
                    <CardTitle className="text-base text-slate-200">请输入密码</CardTitle>
                  </div>
                  <CardDescription className="text-slate-500">
                    密码提示已加密
                  </CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="p-4 bg-slate-900 rounded-lg text-center font-mono">
                    <p className="text-emerald-400 text-lg tracking-wider">
                      {encodedText}
                    </p>
                  </div>

                  <div className="text-sm text-slate-400 space-y-2">
                    <p>档案记录上写着："门后之人，非人非鬼。"</p>
                    {showHint && (
                      <motion.div
                        initial={{ opacity: 0, height: 0 }}
                        animate={{ opacity: 1, height: 'auto' }}
                        className="text-red-400 text-xs bg-red-500/10 px-3 py-2 rounded space-y-1"
                      >
                         <p>💡 提示1：这种编码方式在网页里到处都是——名字里带个数字，把二进制数据变成可打印的文字。</p>
                         <p>💡 提示2：解出来是一串数字，跟 74 和 68 有关。</p>
                        {showDecode && (
                          <p className="text-emerald-400 font-mono pt-1 border-t border-red-500/30 mt-2">
                            解码结果：{base64Decode(encodedText)}
                          </p>
                        )}
                        {!showDecode && (
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => setShowDecode(true)}
                            className="text-xs w-full mt-1 border-red-500/40 text-red-400 hover:bg-red-500/10"
                          >
                            帮我解码
                          </Button>
                        )}
                      </motion.div>
                    )}
                  </div>

                  <form onSubmit={handleSubmit} className="space-y-3">
                    <div className="space-y-2">
                      <label className="text-sm font-medium text-slate-300">密码</label>
                      <Input
                        type="text"
                        value={answer}
                        onChange={(e) => {
                          setAnswer(e.target.value);
                          setError('');
                        }}
                        placeholder="请输入密码"
                        className="bg-slate-900/50 border-slate-600 text-white placeholder:text-slate-600 font-mono text-lg tracking-widest text-center"
                        autoFocus
                      />
                    </div>

                    <AnimatePresence>
                      {error && (
                        <motion.div
                          initial={{ opacity: 0, height: 0 }}
                          animate={{ opacity: 1, height: 'auto' }}
                          exit={{ opacity: 0, height: 0 }}
                          className="flex items-center gap-2 text-red-400 text-sm bg-red-500/10 px-3 py-2 rounded-md"
                        >
                          <AlertCircle className="w-4 h-4 flex-shrink-0" />
                          {error}
                        </motion.div>
                      )}
                    </AnimatePresence>

                    <div className="flex gap-2">
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        onClick={() => setShowHint(!showHint)}
                        className="flex-1 border-slate-600 text-slate-400 hover:bg-slate-700 hover:text-slate-200"
                      >
                        {showHint ? '隐藏提示' : '查看提示'}
                      </Button>
                      <Button type="submit" className="flex-1 gap-1">
                        开门
                        <ArrowRight className="w-4 h-4" />
                      </Button>
                    </div>
                  </form>
                </CardContent>
              </Card>
            </motion.div>
          ) : (
            <motion.div
              key="success"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              transition={{ duration: 1 }}
              className="text-center py-20"
            >
              <motion.div
                animate={{ scale: [1, 1.2, 1], opacity: [1, 0, 1] }}
                transition={{ duration: 1.5, repeat: Infinity }}
                className="w-24 h-32 mx-auto border-2 border-emerald-500 rounded-t-full bg-gradient-to-b from-emerald-900/50 to-transparent relative mb-8"
              >
                <div className="absolute inset-0 bg-emerald-500/20 rounded-t-full" />
              </motion.div>
              <h2 className="text-2xl font-bold text-emerald-400 mb-2">门已开启</h2>
              <p className="text-slate-400">通往另一边...</p>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      <style>{`
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-6px); }
          75% { transform: translateX(6px); }
        }
        .animate-shake {
          animation: shake 0.4s ease-in-out;
        }
      `}</style>
    </div>
  );
}
