import { useState } from 'react';
import { useGame } from '../GameContext';
import { motion } from 'framer-motion';
import { MOCK_STORY } from '@/data/story';
import {
  Search,
  Filter,
  ShieldAlert,
  AlertTriangle,
  AlertOctagon,
  Info,
  MapPin,
  Globe,
  Clock,
  ChevronRight,
} from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import SceneChrome from '../components/SceneChrome';
import OasTopNav from '../components/OasTopNav';

const levelConfig: Record<string, { icon: any; color: string; bgColor: string; label: string }> = {
  high: {
    icon: AlertOctagon,
    color: 'text-red-600',
    bgColor: 'bg-red-50 border-red-200',
    label: '高危',
  },
  medium: {
    icon: AlertTriangle,
    color: 'text-orange-600',
    bgColor: 'bg-orange-50 border-orange-200',
    label: '中危',
  },
  low: {
    icon: Info,
    color: 'text-blue-600',
    bgColor: 'bg-blue-50 border-blue-200',
    label: '低危',
  },
};

export default function OasAlertsScene() {
  const { goToScene } = useGame();
  const { oas } = MOCK_STORY;
  const [keyword, setKeyword] = useState('');
  const [levelFilter, setLevelFilter] = useState('all');
  const [selectedEvent, setSelectedEvent] = useState<any>(null);

  const filtered = oas.alertEvents.filter((e) => {
    const matchKw =
      !keyword ||
      e.title.includes(keyword) ||
      e.detail.includes(keyword) ||
      e.sourceIp.includes(keyword) ||
      e.location.includes(keyword);
    const matchLevel = levelFilter === 'all' || e.level === levelFilter;
    return matchKw && matchLevel;
  });

  const stats = [
    { label: '高危', value: oas.alertEvents.filter((e) => e.level === 'high').length, color: 'text-red-600', bg: 'bg-red-50' },
    { label: '中危', value: oas.alertEvents.filter((e) => e.level === 'medium').length, color: 'text-orange-600', bg: 'bg-orange-50' },
    { label: '低危', value: oas.alertEvents.filter((e) => e.level === 'low').length, color: 'text-blue-600', bg: 'bg-blue-50' },
    { label: '已拦截', value: '1,247', color: 'text-green-600', bg: 'bg-green-50' },
  ];

  return (
    <div className="min-h-screen bg-[#f0f2f5]">
      <SceneChrome variant="system" />
      <OasTopNav activeTab="alerts" />

      <div className="max-w-6xl mx-auto px-4 py-5">
        {/* 面包屑 */}
        <div className="text-xs text-gray-500 mb-4">
          <button
            onClick={() => goToScene('oasDashboard')}
            className="hover:text-[#1e5b9d]"
          >
            工作台
          </button>
          <span className="mx-1">/</span>
          <span className="text-gray-700">预警中心</span>
        </div>

        <motion.div
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.3 }}
          className="space-y-4"
        >
          {/* 预警概览 */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            {stats.map((stat, i) => (
              <div
                key={i}
                className={`${stat.bg} border border-gray-200 p-4`}
              >
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-xs text-gray-600">{stat.label}</p>
                    <p className={`text-2xl font-bold tabular-nums ${stat.color}`}>
                      {stat.value}
                    </p>
                  </div>
                  <ShieldAlert className={`w-6 h-6 ${stat.color} opacity-50`} />
                </div>
              </div>
            ))}
          </div>

          {/* 搜索筛选 */}
          <div className="bg-white border border-gray-200 p-4">
            <div className="flex flex-wrap items-center gap-3">
              <div className="relative flex-1 min-w-[200px]">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <Input
                  type="search"
                  value={keyword}
                  onChange={(e) => setKeyword(e.target.value)}
                  placeholder="搜索事件标题 / 详情 / IP / 位置"
                  className="pl-9 h-9 text-sm"
                />
              </div>
              <div className="flex items-center gap-2">
                <Filter className="w-4 h-4 text-gray-500" />
                <select
                  value={levelFilter}
                  onChange={(e) => setLevelFilter(e.target.value)}
                  className="h-9 px-3 text-sm border border-gray-300 rounded bg-white text-gray-700 focus:outline-none focus:border-[#1e5b9d]"
                >
                  <option value="all">全部级别</option>
                  <option value="high">高危</option>
                  <option value="medium">中危</option>
                  <option value="low">低危</option>
                </select>
              </div>
            </div>
          </div>

          {/* 预警事件列表 */}
          <div className="bg-white border border-gray-200">
            <div className="border-b border-gray-200 px-4 py-3">
              <h2 className="text-sm font-medium text-gray-800">
                安全预警事件
                <span className="text-xs text-gray-500 ml-2">
                  共 {filtered.length} 条
                </span>
              </h2>
            </div>

            <div className="divide-y divide-gray-100">
              {filtered.map((event, i) => {
                const cfg = levelConfig[event.level] || levelConfig.low;
                const Icon = cfg.icon;
                return (
                    <motion.div
                      key={event.id}
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      transition={{ delay: i * 0.05 }}
                      onClick={() => setSelectedEvent(event)}
                      className="p-4 hover:bg-gray-50 cursor-pointer transition-colors"
                    >
                    <div className="flex items-start gap-3">
                      <div className={`w-10 h-10 ${cfg.bgColor} flex items-center justify-center flex-shrink-0 mt-0.5 rounded`}>
                        <Icon className={`w-5 h-5 ${cfg.color}`} />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 flex-wrap">
                          <h3 className="text-sm font-medium text-gray-800">
                            {event.title}
                          </h3>
                          <span
                            className={`text-xs px-1.5 py-0.5 ${cfg.bgColor} ${cfg.color} border`}
                          >
                            {cfg.label}
                          </span>
                          <span className="text-xs text-gray-400 flex items-center gap-1 ml-auto">
                            <Clock className="w-3 h-3" />
                            {event.time}
                          </span>
                        </div>
                        <p className="text-xs text-gray-600 mt-2 leading-relaxed">
                          {event.detail}
                        </p>
                        <div className="mt-2 flex items-center gap-4 text-xs text-gray-500 flex-wrap">
                          <span className="flex items-center gap-1">
                            <Globe className="w-3 h-3" />
                            来源IP：<span className="font-mono">{event.sourceIp}</span>
                          </span>
                          <span className="flex items-center gap-1">
                            <MapPin className="w-3 h-3" />
                            {event.location}
                          </span>
                        </div>
                      </div>
                      <span className="text-xs text-[#1e5b9d] flex items-center gap-1 flex-shrink-0 mt-1" onClick={(e) => { e.stopPropagation(); setSelectedEvent(event); }}>
                        查看详情
                        <ChevronRight className="w-3 h-3" />
                      </span>
                    </div>
                  </motion.div>
                );
              })}
            </div>

            {filtered.length === 0 && (
              <div className="p-12 text-center text-gray-400 text-sm">
                暂无匹配的预警事件
              </div>
            )}
          </div>

          {/* 详情弹窗 */}
          <Dialog open={!!selectedEvent} onOpenChange={(open) => !open && setSelectedEvent(null)}>
            <DialogContent className="max-w-md">
              <DialogHeader>
                <DialogTitle className="text-base">{selectedEvent?.title}</DialogTitle>
                <DialogDescription>
                  {selectedEvent && levelConfig[selectedEvent.level]?.label}级别预警 · {selectedEvent?.time}
                </DialogDescription>
              </DialogHeader>
              <div className="space-y-4 pt-2">
                <p className="text-sm text-gray-700 leading-relaxed">{selectedEvent?.detail}</p>
                <div className="grid grid-cols-2 gap-3 text-xs bg-gray-50 rounded p-3">
                  <div>
                    <p className="text-gray-400 mb-1">来源IP</p>
                    <p className="font-mono text-gray-700">{selectedEvent?.sourceIp}</p>
                  </div>
                  <div>
                    <p className="text-gray-400 mb-1">地理位置</p>
                    <p className="text-gray-700">{selectedEvent?.location}</p>
                  </div>
                  <div>
                    <p className="text-gray-400 mb-1">目标系统</p>
                    <p className="text-gray-700">{selectedEvent?.targetSystem || 'OAS主系统'}</p>
                  </div>
                  <div>
                    <p className="text-gray-400 mb-1">攻击类型</p>
                    <p className="text-gray-700">{selectedEvent?.attackType || '异常访问'}</p>
                  </div>
                </div>
                <div className="bg-yellow-50 border border-yellow-200 rounded p-3 text-xs text-yellow-800 leading-relaxed">
                  <p className="font-medium mb-1">处置建议</p>
                  <p>该IP已自动加入临时封禁列表，封禁时长24小时。建议人工复核后决定是否延长封禁并追溯来源。</p>
                </div>
              </div>
            </DialogContent>
          </Dialog>

          {/* 安全提示 */}
          <div className="bg-blue-50 border border-blue-200 rounded p-4">
            <div className="flex items-start gap-3">
              <ShieldAlert className="w-5 h-5 text-[#1e5b9d] flex-shrink-0 mt-0.5" />
              <div className="text-xs text-blue-800 space-y-1">
                <p className="font-medium">安全提示</p>
                <p>近期境外代理节点针对OAS系统的攻击频次显著上升，攻击特征与邪教组织"十八层"高度吻合。</p>
                <p>请各器官协调员务必保管好账号密码，定期修改，不要在公共网络环境下登录系统。如发现异常操作请立即上报信息安全部门。</p>
              </div>
            </div>
          </div>
        </motion.div>
      </div>
    </div>
  );
}
