import { useState, useEffect } from 'react';
import { useGame } from '../GameContext';
import { motion, AnimatePresence } from 'framer-motion';
import { MOCK_STORY } from '@/data/story';

export default function OpeningScene() {
  const { goToScene } = useGame();
  const [showText, setShowText] = useState(false);
  const [showHint, setShowHint] = useState(false);
  const [fading, setFading] = useState(false);

  useEffect(() => {
    const t1 = setTimeout(() => setShowText(true), 800);
    const t2 = setTimeout(() => setShowHint(true), 2000);
    return () => {
      clearTimeout(t1);
      clearTimeout(t2);
    };
  }, []);

  const handleClick = () => {
    setFading(true);
    setTimeout(() => {
      goToScene('oasLogin');
    }, 800);
  };

  // 心跳动画
  const heartScale = [1, 1.15, 1];

  return (
    <div
      className="fixed inset-0 bg-black flex flex-col items-center justify-center cursor-pointer z-0"
      onClick={handleClick}
    >
      <AnimatePresence>
        {!fading ? (
          <motion.div
            key="content"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 1 }}
            className="text-center px-6"
          >
            {/* 心跳图标效果 */}
            <motion.div
              animate={{ scale: heartScale }}
              transition={{
                duration: 1,
                repeat: Infinity,
                ease: 'easeInOut',
                times: [0, 0.2, 1],
              }}
              className="mb-12"
            >
              <div className="w-16 h-16 mx-auto relative">
                <div className="absolute inset-0 bg-red-600/20 rounded-full blur-xl" />
                <div className="absolute inset-2 bg-red-500/40 rounded-full blur-lg" />
              </div>
            </motion.div>

            {showText && (
              <motion.p
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 1.2 }}
                className="text-gray-300 text-base md:text-lg tracking-widest mb-4"
              >
                {MOCK_STORY.opening.disclaimer}
              </motion.p>
            )}

            {showHint && (
              <motion.p
                initial={{ opacity: 0 }}
                animate={{ opacity: [0.3, 1, 0.3] }}
                transition={{
                  duration: 2,
                  repeat: Infinity,
                  ease: 'easeInOut',
                }}
                className="text-gray-500 text-sm mt-16"
              >
                {MOCK_STORY.opening.hint}
              </motion.p>
            )}

            {showText && (
              <motion.h1
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 1.5, delay: 0.5 }}
                className="text-3xl md:text-5xl font-bold text-white mt-16 tracking-wider"
              >
                末栏
              </motion.h1>
            )}

            {showHint && (
              <motion.p
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ duration: 1, delay: 1 }}
                className="text-gray-400 text-sm mt-3 tracking-[0.3em]"
              >
                · ARG三部曲 ·
              </motion.p>
            )}
          </motion.div>
        ) : (
          <motion.div
            key="fade"
            initial={{ opacity: 1 }}
            animate={{ opacity: 0 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.8 }}
            className="absolute inset-0 bg-black"
          />
        )}
      </AnimatePresence>
    </div>
  );
}
