import { useGame } from '../GameContext';
import { motion } from 'framer-motion';
import { MOCK_STORY } from '@/data/story';
import { Heart, Wrench, Search, ChevronRight, Filter } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { useState } from 'react';
import SceneChrome from '../components/SceneChrome';
import OasTopNav from '../components/OasTopNav';

export default function OasArchivesScene() {
  const { goToScene } = useGame();
  const { oas } = MOCK_STORY;
  const [keyword, setKeyword] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');

  const filtered = oas.archives.filter((a) => {
    const matchKeyword =
      !keyword ||
      a.name.includes(keyword) ||
      a.archiveNo.includes(keyword) ||
      a.city.includes(keyword);
    const matchStatus = filterStatus === 'all' || a.status === filterStatus;
    return matchKeyword && matchStatus;
  });

  const handleArchiveClick = (archiveId: string) => {
    if (archiveId === 'shenchi') {
      goToScene('shenchiPuzzle');
    } else if (archiveId === 'shenbo') {
      goToScene('shenboPuzzle');
    }
  };

  return (
    <div className="min-h-screen bg-[#f0f2f5]">
      <SceneChrome variant="system" />
      <OasTopNav activeTab="archives" />

      <div className="max-w-6xl mx-auto px-4 py-5">
        {/* 面包屑 */}
        <div className="text-xs text-gray-500 mb-4">
          <button
            onClick={() => goToScene('oasDashboard')}
            className="hover:text-[#1e5b9d]"
          >
            工作台
          </button>
          <span className="mx-1">/</span>
          <span className="text-gray-700">档案管理</span>
        </div>

        <motion.div
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.3 }}
          className="space-y-4"
        >
          {/* 搜索筛选栏 */}
          <div className="bg-white border border-gray-200 p-4">
            <div className="flex flex-wrap items-center gap-3">
              <div className="relative flex-1 min-w-[200px]">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <Input
                  type="search"
                  value={keyword}
                  onChange={(e) => setKeyword(e.target.value)}
                  placeholder="搜索姓名 / 档案编号 / 城市"
                  className="pl-9 h-9 text-sm"
                />
              </div>
              <div className="flex items-center gap-2">
                <Filter className="w-4 h-4 text-gray-500" />
                <select
                  value={filterStatus}
                  onChange={(e) => setFilterStatus(e.target.value)}
                  className="h-9 px-3 text-sm border border-gray-300 rounded bg-white text-gray-700 focus:outline-none focus:border-[#1e5b9d]"
                >
                  <option value="all">全部状态</option>
                  <option value="术后异常">术后异常</option>
                  <option value="仪器异常">仪器异常</option>
                  <option value="正常随访">正常随访</option>
                </select>
              </div>
            </div>
          </div>

          {/* 档案列表 */}
          <div className="bg-white border border-gray-200">
            <div className="border-b border-gray-200 px-4 py-3 flex items-center justify-between">
              <h2 className="text-sm font-medium text-gray-800">
                档案列表
                <span className="text-xs text-gray-500 ml-2">
                  共 {filtered.length} 条
                </span>
              </h2>
            </div>

            <div className="divide-y divide-gray-100">
              {filtered.map((archive, i) => (
                <motion.div
                  key={archive.id}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ delay: i * 0.05 }}
                  onClick={() => handleArchiveClick(archive.id)}
                  className={`p-4 hover:bg-blue-50/30 cursor-pointer transition-colors ${
                    archive.status.includes('异常')
                      ? 'border-l-2 border-l-red-500'
                      : 'border-l-2 border-l-transparent'
                  }`}
                >
                  <div className="flex items-start gap-3">
                    <div
                      className={`w-10 h-10 flex items-center justify-center flex-shrink-0 mt-0.5 ${
                        archive.id === 'shenchi'
                          ? 'bg-red-50'
                          : 'bg-amber-50'
                      }`}
                    >
                      {archive.id === 'shenchi' ? (
                        <Heart className="w-4 h-4 text-red-600" />
                      ) : (
                        <Wrench className="w-4 h-4 text-amber-600" />
                      )}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 flex-wrap">
                        <h3 className="text-sm font-medium text-gray-800">
                          {archive.name}
                        </h3>
                        <span
                          className={`text-xs px-1.5 py-0.5 ${
                            archive.status.includes('异常')
                              ? 'bg-red-500 text-white'
                              : 'bg-green-100 text-green-700'
                          }`}
                        >
                          {archive.status}
                        </span>
                        <span className="text-xs text-gray-400 font-mono">
                          {archive.archiveNo}
                        </span>
                      </div>
                      <div className="text-xs text-gray-500 mt-1 flex items-center gap-2 flex-wrap">
                        <span>{archive.age}岁</span>
                        <span className="text-gray-300">|</span>
                        <span>{archive.city}</span>
                        <span className="text-gray-300">|</span>
                        <span>{archive.organType}</span>
                        <span className="text-gray-300">|</span>
                        <span>手术日期：{archive.transplantDate}</span>
                      </div>
                      <p className="text-xs text-gray-600 mt-2 leading-relaxed">
                        {archive.description}
                      </p>
                      <div className="text-xs text-gray-400 mt-2">
                        随访记录：{archive.followUpRecords.length} 条
                      </div>
                    </div>
                    <div className="flex items-center gap-1 text-xs text-[#1e5b9d] flex-shrink-0 mt-1">
                      查看详情
                      <ChevronRight className="w-3 h-3" />
                    </div>
                  </div>
                </motion.div>
              ))}
            </div>

            {filtered.length === 0 && (
              <div className="p-12 text-center text-gray-400 text-sm">
                未找到符合条件的档案
              </div>
            )}
          </div>
        </motion.div>
      </div>
    </div>
  );
}
