function FinalEpilogue({ onDone }: FinalEpilogueProps) {
  // 已显示的段落数：0 = 还没开始, 1 = 显示了鲍达人段, ..., 5 = 全部显示完
  const [visibleCount, setVisibleCount] = useState(0);
  // 最后一段全部显示完，玩家再点一次 → 进入第四面墙
  const [canExit, setCanExit] = useState(false);

  const handleAdvance = useCallback(() => {
    // 全部显示完且可以退出 → 进入第四面墙
    if (canExit) {
      onDone();
      return;
    }
    // 还没全部显示完 → 显示下一段
    if (visibleCount < EPILOGUE_SECTIONS.length) {
      setVisibleCount(prev => prev + 1);
    }
  }, [visibleCount, canExit, onDone]);

  // 最后一段显示完毕后，标记可退出
  const handleFinalSectionShown = useCallback(() => {
    setCanExit(true);
  }, []);

  return (
    <div
      className="fixed inset-0 bg-gradient-to-b from-stone-950 via-stone-900 to-stone-950 overflow-hidden flex items-start justify-center px-6 cursor-pointer select-none"
      onClick={handleAdvance}
    >
      {/* 背景轻微噪点 */}
      <div
        className="absolute inset-0 opacity-30 pointer-events-none"
        style={{
          backgroundImage:
            'radial-gradient(circle at 50% 50%, rgba(120,113,108,0.1) 0%, transparent 70%)',
        }}
      />

      <div className="relative w-full max-w-md mx-auto space-y-10 py-16 md:py-20">
        {EPILOGUE_SECTIONS.map((sec, i) => {
          const isVisible = visibleCount > i;
          const isLast = i === EPILOGUE_SECTIONS.length - 1;
          return (
            <AnimatePresence key={i} mode="wait">
              {isVisible && (
                <motion.div
                  key={`sec-${i}`}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0 }}
                  transition={{ duration: 1.5, ease: 'easeOut' }}
                  onAnimationComplete={() => {
                    if (isLast) handleFinalSectionShown();
                  }}
                  className="space-y-2 text-center"
                >
                  <p
                    className={`text-[11px] tracking-[0.3em] mb-4 ${
                      sec.isFinal ? 'text-rose-500/60' : 'text-stone-500/60'
                    }`}
                  >
                    — {sec.title} —
                  </p>
                  {sec.paragraphs.map((p, pi) => (
                    <motion.p
                      key={pi}
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      transition={{ delay: pi * 0.2, duration: 0.8 }}
                      className={`text-sm leading-loose ${
                        sec.isFinal
                          ? pi >= sec.paragraphs.length - 3
                            ? 'text-rose-400/80'
                            : 'text-stone-400/80'
                          : 'text-stone-400/80'
                      }`}
                    >
                      {p || '\u00A0'}
                    </motion.p>
                  ))}
                </motion.div>
              )}
            </AnimatePresence>
          );
        })}

        {/* 点击继续提示 */}
        <AnimatePresence>
          {!canExit && visibleCount > 0 && visibleCount < EPILOGUE_SECTIONS.length && (
            <motion.p
              initial={{ opacity: 0 }}
              animate={{ opacity: [0.3, 0.8, 0.3] }}
              transition={{ duration: 2.5, repeat: Infinity, ease: 'easeInOut' }}
              className="text-center text-[10px] text-stone-600 pt-4"
            >
              点击继续
            </motion.p>
          )}
        </AnimatePresence>

        {/* 全部结束后的退出提示 */}
        <AnimatePresence>
          {canExit && (
            <motion.p
              initial={{ opacity: 0 }}
              animate={{ opacity: [0.3, 0.7, 0.3] }}
              transition={{ duration: 2.5, repeat: Infinity, ease: 'easeInOut' }}
              className="text-center text-[10px] text-stone-600 pt-6"
            >
              点击结束
            </motion.p>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

export default memo(FinalEpilogue);
