import { createContext, useContext, useReducer, useCallback, useEffect, type ReactNode } from 'react';

// ===== 类型定义 =====
export type SceneId =
  | 'opening'
  | 'oasLogin'
  | 'oasDashboard'
  | 'oasArchives'
  | 'oasAllocation'
  | 'oasFollowup'
  | 'oasAlerts'
  | 'oasArchiveDetail'
  | 'shenchiPuzzle'
  | 'shenboPuzzle'
  | 'instituteHome'
  | 'instituteAbout'
  | 'instituteNews'
  | 'instituteArchive'
  | 'heartCenter'
  | 'equipmentDept'
  | 'door1Puzzle'
  | 'panyangHome'
  | 'panyangAbout'
  | 'panyangBusiness'
  | 'panyangProducts'
  | 'panyangNews'
  | 'panyangMap'
  | 'panyangContact'
  | 'huaxiaForum'
  | 'shibacengLogin'
  | 'shibacengForum'
  | 'scripturePuzzle'
  | 'shenchiView'
  | 'shenboView'
  | 'finalDoor'
  | 'endingChat'
  | 'dutyKeeper'
  | 'badEnding'
  | 'goodEnding'
  | 'hiddenEnding'
  | 'fakeEnding'
  | 'hospitalRepairLogin'
  | 'hospitalRepairList'
  | 'panyangStaffLogin'
  | 'panyangStaffHome'
  | 'myRecord';

export type ClueId = 'recordCode' | 'cityList' | 'instrumentCode' | 'scripture' | 'sisterNote';

export interface IClue {
  id: ClueId;
  name: string;
  description: string;
  found: boolean;
  foundScene?: SceneId;
}

export interface IPuzzleProgress {
  oasLogin: boolean;
  shenchiPuzzle: boolean;
  shenboPuzzle: boolean;
  door1Puzzle: boolean;
  shibacengLogin: boolean;
  scripturePuzzle: boolean;
  shenchiLogin: boolean;
  shenboLogin: boolean;
  shenchiWarned: boolean;
  shenboWarned: boolean;
  finalDoor: boolean;
  hiddenScroll1: boolean; // 萧老师的加密笔记
  hiddenScroll2: boolean; // 十二城样本编号地图
  hiddenScroll3: boolean; // 走廊片段
  hiddenScroll4: boolean; // 值班的记录
  shenchiChoice: 'none' | 'persuade' | 'letgo'; // 对沈迟停药的选择
  shenboChoice: 'none' | 'persuade' | 'open'; // 对沈搏听录音的选择
  shenchiLineUnlocked: boolean; // 是否解锁沈迟线（进入过患者端视角）
  shenboLineUnlocked: boolean; // 是否解锁沈搏线（进入过报修系统）
}

export type VisitorIdentity = 'chengwei' | 'shenchi' | 'shenbo';

export interface IGameState {
  currentScene: SceneId;
  sceneHistory: SceneId[];
  clues: Record<ClueId, IClue>;
  puzzleProgress: IPuzzleProgress;
  shenchiSaved: boolean;
  shenboSaved: boolean;
  unlockedEndings: string[];
  muted: boolean;
  visitorIdentity: VisitorIdentity;
  hasCompletedRun: boolean; // 二周目标志：是否至少通关过一次结局
  fakeEndingEntry: 'choice' | 'snapshot'; // 进入fakeEnding的方式：choice=选择不去/snapshot=随手拍（强制none-saved）
}

// ===== 初始状态 =====
const initialClues: Record<ClueId, IClue> = {
  recordCode: { id: 'recordCode', name: '1974年纪录', description: '"它"最早在1974年被记录', found: false },
  cityList: { id: 'cityList', name: '十二城市布局', description: '十二个城市，十二只手托起新生', found: false },
  instrumentCode: { id: 'instrumentCode', name: '仪器声明', description: 'YQSM = 仪器声明', found: false },
  scripture: { id: 'scripture', name: '经书密文', description: 'BEHIND — 它在你身后', found: false },
  sisterNote: { id: 'sisterNote', name: '姐妹笔记', description: '研究所地址，就是殡仪馆地址', found: false },
};

const initialPuzzleProgress: IPuzzleProgress = {
  oasLogin: false,
  shenchiPuzzle: false,
  shenboPuzzle: false,
  door1Puzzle: false,
  shibacengLogin: false,
  scripturePuzzle: false,
  shenchiLogin: false,
  shenboLogin: false,
  shenchiWarned: false,
  shenboWarned: false,
  finalDoor: false,
  hiddenScroll1: false,
  hiddenScroll2: false,
  hiddenScroll3: false,
  hiddenScroll4: false,
  shenchiChoice: 'none',
  shenboChoice: 'none',
  shenchiLineUnlocked: false,
  shenboLineUnlocked: false,
};

const MUTE_STORAGE_KEY = 'game_molan_muted';
const COMPLETED_KEY = 'molan_has_completed';

function getInitialMuted(): boolean {
  try {
    const saved = localStorage.getItem(MUTE_STORAGE_KEY);
    return saved === 'true';
  } catch {
    return false;
  }
}

function getInitialCompleted(): boolean {
  try {
    const saved = localStorage.getItem(COMPLETED_KEY);
    return saved === 'true';
  } catch {
    return false;
  }
}

const initialState: IGameState = {
  currentScene: 'opening',
  sceneHistory: [],
  clues: initialClues,
  puzzleProgress: initialPuzzleProgress,
  shenchiSaved: false,
  shenboSaved: false,
  unlockedEndings: [],
  muted: getInitialMuted(),
  visitorIdentity: 'chengwei',
  hasCompletedRun: getInitialCompleted(),
  fakeEndingEntry: 'choice',
};

// ===== Actions =====
type GameAction =
  | { type: 'GO_TO_SCENE'; scene: SceneId }
  | { type: 'GO_BACK' }
  | { type: 'FIND_CLUE'; clueId: ClueId; scene: SceneId }
  | { type: 'SET_PUZZLE_DONE'; key: keyof IPuzzleProgress }
  | { type: 'SAVE_SHENCHI' }
  | { type: 'SAVE_SHENBO' }
  | { type: 'UNLOCK_ENDING'; ending: string }
  | { type: 'TOGGLE_MUTE' }
  | { type: 'SET_VISITOR_IDENTITY'; identity: VisitorIdentity }
  | { type: 'RESET_GAME' }
  | { type: 'LOAD_STATE'; state: IGameState }
  | { type: 'SET_SHENCHI_CHOICE'; choice: 'persuade' | 'letgo' }
  | { type: 'SET_SHENBO_CHOICE'; choice: 'persuade' | 'open' }
  | { type: 'UNLOCK_SHENCHI_LINE' }
  | { type: 'UNLOCK_SHENBO_LINE' }
  | { type: 'SET_FAKE_ENDING_ENTRY'; entry: 'choice' | 'snapshot' };

function gameReducer(state: IGameState, action: GameAction): IGameState {
  switch (action.type) {
    case 'GO_TO_SCENE':
      if (action.scene === state.currentScene) return state;
      return {
        ...state,
        sceneHistory: [...state.sceneHistory, state.currentScene],
        currentScene: action.scene,
      };
    case 'GO_BACK': {
      if (state.sceneHistory.length === 0) return state;
      const prev = state.sceneHistory[state.sceneHistory.length - 1];
      return {
        ...state,
        sceneHistory: state.sceneHistory.slice(0, -1),
        currentScene: prev,
      };
    }
    case 'FIND_CLUE': {
      if (state.clues[action.clueId].found) return state;
      return {
        ...state,
        clues: {
          ...state.clues,
          [action.clueId]: {
            ...state.clues[action.clueId],
            found: true,
            foundScene: action.scene,
          },
        },
      };
    }
    case 'SET_PUZZLE_DONE':
      return {
        ...state,
        puzzleProgress: {
          ...state.puzzleProgress,
          [action.key]: true,
        },
      };
    case 'SAVE_SHENCHI':
      return { ...state, shenchiSaved: true };
    case 'SAVE_SHENBO':
      return { ...state, shenboSaved: true };
    case 'UNLOCK_ENDING':
       if (state.unlockedEndings.includes(action.ending)) return state;
       // 首次解锁结局时，写入二周目标志（跨重置保留）
       try {
         localStorage.setItem(COMPLETED_KEY, 'true');
       } catch {
         // 忽略
       }
       return {
         ...state,
         unlockedEndings: [...state.unlockedEndings, action.ending],
         hasCompletedRun: true,
       };
    case 'TOGGLE_MUTE':
      return { ...state, muted: !state.muted };
    case 'SET_VISITOR_IDENTITY':
      return { ...state, visitorIdentity: action.identity };
    case 'SET_SHENCHI_CHOICE':
      return {
        ...state,
        puzzleProgress: { ...state.puzzleProgress, shenchiChoice: action.choice },
      };
    case 'SET_SHENBO_CHOICE':
      return {
        ...state,
        puzzleProgress: { ...state.puzzleProgress, shenboChoice: action.choice },
      };
    case 'UNLOCK_SHENCHI_LINE':
      if (state.puzzleProgress.shenchiLineUnlocked) return state;
      return {
        ...state,
        puzzleProgress: { ...state.puzzleProgress, shenchiLineUnlocked: true },
      };
    case 'UNLOCK_SHENBO_LINE':
      if (state.puzzleProgress.shenboLineUnlocked) return state;
      return {
        ...state,
        puzzleProgress: { ...state.puzzleProgress, shenboLineUnlocked: true },
      };
    case 'SET_FAKE_ENDING_ENTRY':
      return {
        ...state,
        fakeEndingEntry: action.entry,
      };
    case 'RESET_GAME':
      return { ...initialState };
    case 'LOAD_STATE':
      return action.state;
    default:
      return state;
  }
}

// ===== Context =====
interface IGameContext {
  state: IGameState;
  goToScene: (scene: SceneId) => void;
  setFakeEndingEntry: (entry: 'choice' | 'snapshot') => void;
  goBack: () => void;
  canGoBack: boolean;
  findClue: (clueId: ClueId, scene: SceneId) => void;
  setPuzzleDone: (key: keyof IPuzzleProgress) => void;
  saveShenchi: () => void;
  saveShenbo: () => void;
  unlockEnding: (ending: string) => void;
  toggleMute: () => void;
  setVisitorIdentity: (identity: VisitorIdentity) => void;
  hasCompletedRun: boolean;
   resetGame: () => void;
   allCluesFound: boolean;
  canTriggerFinalDoor: boolean;
  setShenchiChoice: (choice: 'persuade' | 'letgo') => void;
  setShenboChoice: (choice: 'persuade' | 'open') => void;
  unlockShenchiLine: () => void;
  unlockShenboLine: () => void;
}

const GameContext = createContext<IGameContext | null>(null);

export function GameProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(gameReducer, initialState);

  // 注意：不使用 localStorage 持久化，刷新页面从头开始游戏
  // 唯一例外：隐藏线解锁状态 + 两个结局选择持久化（跨周目发现）
  useEffect(() => {
    try {
      const shenchi = localStorage.getItem('__game_molan_choice_shenchi');
      const shenbo = localStorage.getItem('__game_molan_choice_shenbo');
      const shenchiUnlocked = localStorage.getItem('__game_molan_unlock_shenchi');
      const shenboUnlocked = localStorage.getItem('__game_molan_unlock_shenbo');
      if (shenchi === 'persuade' || shenchi === 'letgo') {
        dispatch({ type: 'SET_SHENCHI_CHOICE', choice: shenchi });
      }
      if (shenbo === 'persuade' || shenbo === 'open') {
        dispatch({ type: 'SET_SHENBO_CHOICE', choice: shenbo });
      }
      if (shenchiUnlocked === '1') {
        dispatch({ type: 'UNLOCK_SHENCHI_LINE' });
      }
      if (shenboUnlocked === '1') {
        dispatch({ type: 'UNLOCK_SHENBO_LINE' });
      }
    } catch {
      // 忽略
    }
  }, []);

  // 浏览器返回键支持
  useEffect(() => {
    const handlePopState = () => {
      dispatch({ type: 'GO_BACK' });
    };
    window.addEventListener('popstate', handlePopState);
    // 确保页面加载时历史状态清空，从开场开始
    try {
      window.history.replaceState(null, '');
    } catch {
      // 忽略
    }
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  const goToScene = useCallback((scene: SceneId) => {
    dispatch({ type: 'GO_TO_SCENE', scene });
    try {
      window.history.pushState({ scene }, '');
    } catch {
      // 忽略
    }
  }, []);

  const goBack = useCallback(() => {
    dispatch({ type: 'GO_BACK' });
  }, []);

  const findClue = useCallback((clueId: ClueId, scene: SceneId) => {
    dispatch({ type: 'FIND_CLUE', clueId, scene });
  }, []);

  const setPuzzleDone = useCallback((key: keyof IPuzzleProgress) => {
    dispatch({ type: 'SET_PUZZLE_DONE', key });
  }, []);

  const saveShenchi = useCallback(() => {
    dispatch({ type: 'SAVE_SHENCHI' });
  }, []);

  const saveShenbo = useCallback(() => {
    dispatch({ type: 'SAVE_SHENBO' });
  }, []);

  const unlockEnding = useCallback((ending: string) => {
    dispatch({ type: 'UNLOCK_ENDING', ending });
  }, []);

  const toggleMute = useCallback(() => {
    dispatch({ type: 'TOGGLE_MUTE' });
    try {
      const next = !state.muted;
      localStorage.setItem(MUTE_STORAGE_KEY, String(next));
    } catch {
      // 忽略
    }
  }, [state.muted]);

  const setVisitorIdentity = useCallback((identity: VisitorIdentity) => {
    dispatch({ type: 'SET_VISITOR_IDENTITY', identity });
  }, []);

  const setShenchiChoice = useCallback((choice: 'persuade' | 'letgo') => {
    dispatch({ type: 'SET_SHENCHI_CHOICE', choice });
    try {
      localStorage.setItem('__game_molan_choice_shenchi', choice);
    } catch {
      // 忽略
    }
  }, []);

  const setShenboChoice = useCallback((choice: 'persuade' | 'open') => {
    dispatch({ type: 'SET_SHENBO_CHOICE', choice });
    try {
      localStorage.setItem('__game_molan_choice_shenbo', choice);
    } catch {
      // 忽略
    }
  }, []);

  const unlockShenchiLine = useCallback(() => {
    dispatch({ type: 'UNLOCK_SHENCHI_LINE' });
    try {
      localStorage.setItem('__game_molan_unlock_shenchi', '1');
    } catch {
      // 忽略
    }
  }, []);

  const unlockShenboLine = useCallback(() => {
    dispatch({ type: 'UNLOCK_SHENBO_LINE' });
    try {
      localStorage.setItem('__game_molan_unlock_shenbo', '1');
    } catch {
      // 忽略
    }
  }, []);

  const setFakeEndingEntry = useCallback((entry: 'choice' | 'snapshot') => {
    dispatch({ type: 'SET_FAKE_ENDING_ENTRY', entry });
  }, []);

  const resetGame = useCallback(() => {
    // 清空所有游戏进度的 localStorage
    try {
      const keysToRemove: string[] = [];
      for (let i = 0; i < window.localStorage.length; i++) {
        const key = window.localStorage.key(i);
        if (key && (key.startsWith('__game_') || key.startsWith('game_molan'))) {
          keysToRemove.push(key);
        }
      }
      keysToRemove.forEach((k) => window.localStorage.removeItem(k));
    } catch {
      // 忽略
    }
    // 清空历史记录并回到开场页
    try {
      window.history.replaceState(null, '');
    } catch {
      // 忽略
    }
    dispatch({ type: 'RESET_GAME' });
  }, []);

  const canGoBack = state.sceneHistory.length > 0;

  const allCluesFound = Object.values(state.clues).every((c) => c.found);

  const canTriggerFinalDoor =
    state.puzzleProgress.shibacengLogin &&
    state.puzzleProgress.scripturePuzzle &&
    state.puzzleProgress.hiddenScroll1 &&
    state.puzzleProgress.hiddenScroll2 &&
    state.puzzleProgress.hiddenScroll3 &&
    state.puzzleProgress.hiddenScroll4 &&
    Object.values(state.clues).filter((c) => c.found).length >= 3;

  return (
    <GameContext.Provider
      value={{
        state,
        goToScene,
        goBack,
        canGoBack,
        findClue,
        setPuzzleDone,
        saveShenchi,
        saveShenbo,
        unlockEnding,
        toggleMute,
        setVisitorIdentity,
        resetGame,
        allCluesFound,
        canTriggerFinalDoor,
        setShenchiChoice,
        setShenboChoice,
        unlockShenchiLine,
         unlockShenboLine,
         setFakeEndingEntry,
          hasCompletedRun: state.hasCompletedRun,
       }}
    >
      {children}
    </GameContext.Provider>
  );
}

export function useGame() {
  const ctx = useContext(GameContext);
  if (!ctx) throw new Error('useGame must be used within GameProvider');
  return ctx;
}
