import { useState, useEffect } from 'react';
import { useGame } from '../GameContext';
import { Search, X, Lock, ChevronDown, ChevronUp } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { motion, AnimatePresence } from 'framer-motion';

export default function CluePanel() {
  const { state } = useGame();
  const [isCollapsed, setIsCollapsed] = useState(false); // 默认展开
  const [newClueFlash, setNewClueFlash] = useState(false);
  const foundCount = Object.values(state.clues).filter((c) => c.found).length;
  const totalCount = Object.values(state.clues).length;

  // 监听新线索
  useEffect(() => {
    if (foundCount > 0) {
      setNewClueFlash(true);
      const timer = setTimeout(() => setNewClueFlash(false), 3000);
      return () => clearTimeout(timer);
    }
  }, [foundCount]);

  return (
    <AnimatePresence initial={false}>
      {!isCollapsed ? (
        // 展开状态：右下角浮动面板
        <motion.div
          key="expanded"
          initial={{ opacity: 0, y: 20, scale: 0.95 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={{ opacity: 0, y: 20, scale: 0.95 }}
          transition={{ duration: 0.25, ease: 'easeOut' }}
          className="fixed bottom-24 right-4 md:right-8 z-[70] w-[85vw] max-w-xs bg-background/95 backdrop-blur-md border border-border rounded-lg shadow-xl overflow-hidden"
        >
          {/* 头部 */}
          <div className="flex items-center justify-between px-4 py-3 border-b border-border/60 bg-muted/30">
            <div className="flex items-center gap-2">
              <Search className={`w-4 h-4 ${newClueFlash ? 'text-primary animate-pulse' : 'text-muted-foreground'}`} />
              <h3 className="text-sm font-semibold">线索收集</h3>
              <span className="text-xs text-muted-foreground">
                {foundCount}/{totalCount}
              </span>
            </div>
            <Button
              variant="ghost"
              size="icon"
              onClick={() => setIsCollapsed(true)}
              className="h-7 w-7"
              aria-label="收起线索栏"
            >
              <ChevronDown className="w-4 h-4" />
            </Button>
          </div>

          {/* 线索列表 */}
          <div className="max-h-[40vh] overflow-y-auto p-3 space-y-2">
            {Object.values(state.clues).map((clue) => (
              <div
                key={clue.id}
                className={`p-2.5 rounded-md border transition-all ${
                  clue.found
                    ? 'bg-card border-border'
                    : 'bg-muted/30 border-border/50 opacity-60'
                }`}
              >
                <div className="flex items-start gap-2">
                  <div
                    className={`mt-0.5 flex-shrink-0 w-6 h-6 rounded-full flex items-center justify-center ${
                      clue.found ? 'bg-primary/10 text-primary' : 'bg-muted text-muted-foreground'
                    }`}
                  >
                    {clue.found ? (
                      <Search className="w-3 h-3" />
                    ) : (
                      <Lock className="w-3 h-3" />
                    )}
                  </div>
                  <div className="flex-1 min-w-0">
                    <h4 className={`font-medium text-xs ${clue.found ? 'text-foreground' : 'text-muted-foreground'}`}>
                      {clue.found ? clue.name : '???'}
                    </h4>
                    <p className="text-[11px] text-muted-foreground mt-0.5 leading-relaxed line-clamp-2">
                      {clue.found ? clue.description : '尚未发现此线索...'}
                    </p>
                  </div>
                </div>
              </div>
            ))}

            {foundCount === totalCount && (
              <div className="p-3 rounded-md bg-primary/10 border border-primary/30">
                <p className="text-xs text-primary font-medium">全部线索已收集</p>
                <p className="text-[11px] text-muted-foreground mt-0.5">隐藏结局条件已满足</p>
              </div>
            )}
          </div>
        </motion.div>
      ) : (
        // 收起状态：只露一个小图标
        <motion.button
          key="collapsed"
          initial={{ opacity: 0, scale: 0.8 }}
          animate={{ opacity: 1, scale: 1 }}
          exit={{ opacity: 0, scale: 0.8 }}
          transition={{ duration: 0.2 }}
          onClick={() => setIsCollapsed(false)}
          className="fixed bottom-24 right-4 md:right-8 z-[70] w-11 h-11 rounded-full bg-background/90 backdrop-blur-md border border-border shadow-lg flex items-center justify-center hover:bg-accent transition-colors"
          aria-label="展开线索栏"
        >
          <Search className={`w-4 h-4 ${newClueFlash ? 'text-primary animate-pulse' : 'text-muted-foreground'}`} />
          {foundCount > 0 && (
            <span className="absolute -top-1 -right-1 w-5 h-5 bg-primary text-primary-foreground text-[10px] rounded-full flex items-center justify-center font-medium">
              {foundCount}
            </span>
          )}
          <ChevronUp className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-3 h-3 text-muted-foreground" />
        </motion.button>
      )}
    </AnimatePresence>
  );
}
