import { useGame } from '../GameContext';
import { ArrowLeft } from 'lucide-react';

interface SceneChromeProps {
  title?: string;
  variant?: 'light' | 'dark' | 'system' | 'forum' | 'company' | 'institute';
  showBack?: boolean;
}

export default function SceneChrome({ title, variant = 'light', showBack = true }: SceneChromeProps) {
  const { goBack, canGoBack, state, toggleMute } = useGame();

  // 根据场景变体返回不同的顶部栏样式
  const getStyles = () => {
    switch (variant) {
      case 'dark':
        return {
          bg: 'bg-black border-b border-red-900/50',
          text: 'text-red-200/80 hover:text-red-100',
          titleColor: 'text-red-300',
        };
      case 'system':
        return {
          bg: 'bg-[#1e5b9d] border-b border-[#154a82]',
          text: 'text-white/90 hover:text-white',
          titleColor: 'text-white',
        };
      case 'forum':
        return {
          bg: 'bg-[#f5f5e8] border-b border-[#e0dcc8]',
          text: 'text-[#666] hover:text-[#333]',
          titleColor: 'text-[#333]',
        };
      case 'company':
        return {
          bg: 'bg-white border-b border-gray-200',
          text: 'text-gray-600 hover:text-gray-900',
          titleColor: 'text-gray-800',
        };
      case 'institute':
        return {
          bg: 'bg-white border-b border-gray-100',
          text: 'text-gray-500 hover:text-gray-800',
          titleColor: 'text-gray-800',
        };
      default:
        return {
          bg: 'bg-white border-b border-gray-200',
          text: 'text-gray-600 hover:text-gray-900',
          titleColor: 'text-gray-800',
        };
    }
  };

  const styles = getStyles();

  return (
    <div className={`fixed top-0 left-0 right-0 z-[60] ${styles.bg}`}>
      <div className="flex items-center justify-between px-3 md:px-6 h-12">
        <div className="flex items-center gap-2 min-w-0">
          {showBack && canGoBack && (
            <button
              onClick={goBack}
              className={`${styles.text} flex items-center gap-1 text-sm transition-colors`}
            >
              <ArrowLeft className="w-4 h-4" />
              <span className="hidden sm:inline">返回</span>
            </button>
          )}
          {title && (
            <span className={`text-sm font-medium truncate ${styles.titleColor}`}>
              {title}
            </span>
          )}
        </div>
        <div>
          {/* 静音按钮由 AudioController 全局渲染，此处留空保持布局对称 */}
        </div>
      </div>
    </div>
  );
}
