import { useState } from 'react';
import { useGame } from '../GameContext';
import { motion } from 'framer-motion';
import { MOCK_STORY } from '@/data/story';
import { Search, Filter, Calendar, Heart, Activity, Stethoscope, Wind } from 'lucide-react';
import { Input } from '@/components/ui/input';
import SceneChrome from '../components/SceneChrome';
import OasTopNav from '../components/OasTopNav';

const organIconMap: Record<string, any> = {
  心脏: Heart,
  肝脏: Activity,
  肾脏: Stethoscope,
  肺脏: Wind,
};

export default function OasAllocationScene() {
  const { goToScene } = useGame();
  const { oas } = MOCK_STORY;
  const [keyword, setKeyword] = useState('');
  const [organFilter, setOrganFilter] = useState('all');

  const filtered = oas.allocationRecords.filter((r) => {
    const matchKw =
      !keyword ||
      r.recipient.includes(keyword) ||
      r.hospital.includes(keyword) ||
      r.id.includes(keyword);
    const matchOrgan = organFilter === 'all' || r.organType.includes(organFilter);
    return matchKw && matchOrgan;
  });

  const organStats = ['心脏', '肝脏', '肾脏', '肺脏'].map((organ) => ({
    organ,
    count: oas.allocationRecords.filter((r) => r.organType.includes(organ)).length,
  }));

  return (
    <div className="min-h-screen bg-[#f0f2f5]">
      <SceneChrome variant="system" />
      <OasTopNav activeTab="allocation" />

      <div className="max-w-6xl mx-auto px-4 py-5">
        {/* 面包屑 */}
        <div className="text-xs text-gray-500 mb-4">
          <button
            onClick={() => goToScene('oasDashboard')}
            className="hover:text-[#1e5b9d]"
          >
            工作台
          </button>
          <span className="mx-1">/</span>
          <span className="text-gray-700">分配记录</span>
        </div>

        <motion.div
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.3 }}
          className="space-y-4"
        >
          {/* 本月分配统计 */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            {organStats.map((item, i) => {
              const Icon = organIconMap[item.organ] || Heart;
              return (
                <div
                  key={item.organ}
                  className="bg-white border border-gray-200 p-4"
                >
                  <div className="flex items-center gap-3">
                    <div className="w-9 h-9 bg-blue-50 flex items-center justify-center">
                      <Icon className="w-4 h-4 text-[#1e5b9d]" />
                    </div>
                    <div>
                      <p className="text-xs text-gray-500">{item.organ}移植</p>
                      <p className="text-xl font-bold text-gray-800 tabular-nums">
                        {item.count}
                        <span className="text-xs text-gray-400 font-normal ml-1">
                          例
                        </span>
                      </p>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>

          {/* 搜索筛选 */}
          <div className="bg-white border border-gray-200 p-4">
            <div className="flex flex-wrap items-center gap-3">
              <div className="relative flex-1 min-w-[200px]">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <Input
                  type="search"
                  value={keyword}
                  onChange={(e) => setKeyword(e.target.value)}
                  placeholder="搜索受者姓名 / 医院 / 记录编号"
                  className="pl-9 h-9 text-sm"
                />
              </div>
              <div className="flex items-center gap-2">
                <Filter className="w-4 h-4 text-gray-500" />
                <select
                  value={organFilter}
                  onChange={(e) => setOrganFilter(e.target.value)}
                  className="h-9 px-3 text-sm border border-gray-300 rounded bg-white text-gray-700 focus:outline-none focus:border-[#1e5b9d]"
                >
                  <option value="all">全部器官</option>
                  <option value="心脏">心脏</option>
                  <option value="肝脏">肝脏</option>
                  <option value="肾脏">肾脏</option>
                  <option value="肺脏">肺脏</option>
                </select>
              </div>
            </div>
          </div>

          {/* 分配记录表格 */}
          <div className="bg-white border border-gray-200">
            <div className="border-b border-gray-200 px-4 py-3 flex items-center justify-between">
              <h2 className="text-sm font-medium text-gray-800">
                分配记录列表
                <span className="text-xs text-gray-500 ml-2">
                  共 {filtered.length} 条
                </span>
              </h2>
              <div className="flex items-center gap-1 text-xs text-gray-500">
                <Calendar className="w-3 h-3" />
                本月数据
              </div>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="bg-gray-50 border-b border-gray-200">
                    <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-500">
                      记录编号
                    </th>
                    <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-500">
                      分配日期
                    </th>
                    <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-500">
                      器官类型
                    </th>
                    <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-500">
                      供体编号
                    </th>
                    <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-500">
                      受者信息
                    </th>
                    <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-500">
                      手术医院
                    </th>
                    <th className="px-4 py-2.5 text-left text-xs font-medium text-gray-500">
                      结果
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {filtered.map((record) => (
                    <tr key={record.id} className="hover:bg-gray-50">
                      <td className="px-4 py-2.5 text-xs text-gray-600 font-mono">
                        {record.id.toUpperCase()}
                      </td>
                      <td className="px-4 py-2.5 text-xs text-gray-600">
                        {record.date}
                      </td>
                      <td className="px-4 py-2.5 text-xs">
                        <span className="inline-flex items-center gap-1 px-2 py-0.5 bg-blue-50 text-[#1e5b9d] rounded">
                          {record.organType}
                        </span>
                      </td>
                      <td className="px-4 py-2.5 text-xs text-gray-600 font-mono">
                        {record.donor}
                      </td>
                      <td className="px-4 py-2.5 text-xs text-gray-800">
                        {record.recipient}
                      </td>
                      <td className="px-4 py-2.5 text-xs text-gray-600">
                        {record.hospital}
                      </td>
                      <td className="px-4 py-2.5 text-xs">
                        <span className="text-green-600">{record.result}</span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {filtered.length === 0 && (
              <div className="p-12 text-center text-gray-400 text-sm">
                暂无匹配的分配记录
              </div>
            )}
          </div>
        </motion.div>
      </div>
    </div>
  );
}
