import { useGame } from '../GameContext';
import { motion } from 'framer-motion';
import { MOCK_STORY } from '@/data/story';
import {
  Heart,
  Wrench,
  User,
  Calendar,
  FileText,
  MapPin,
  Archive,
} from 'lucide-react';
import SceneChrome from '../components/SceneChrome';
import OasTopNav from '../components/OasTopNav';

interface OasArchiveDetailSceneProps {
  archiveId: string;
}

export default function OasArchiveDetailScene({
  archiveId,
}: OasArchiveDetailSceneProps) {
  const { goToScene } = useGame();
  const { oas } = MOCK_STORY;
  const archive = oas.archives.find((a) => a.id === archiveId);

  if (!archive) {
    return (
      <div className="min-h-screen bg-[#f0f2f5]">
        <SceneChrome variant="system" />
        <div className="max-w-4xl mx-auto px-4 py-20 text-center text-gray-500">
          档案不存在
        </div>
      </div>
    );
  }

  const Icon = archive.id === 'shenchi' ? Heart : Wrench;
  const iconBg = archive.id === 'shenchi' ? 'bg-red-50' : 'bg-amber-50';
  const iconColor = archive.id === 'shenchi' ? 'text-red-600' : 'text-amber-600';

  return (
    <div className="min-h-screen bg-[#f0f2f5]">
      <SceneChrome variant="system" />
      <OasTopNav activeTab="archives" />

      <div className="max-w-4xl mx-auto px-4 py-5">
        {/* 面包屑 */}
        <div className="text-xs text-gray-500 mb-4">
          <button
            onClick={() => goToScene('oasDashboard')}
            className="hover:text-[#1e5b9d]"
          >
            工作台
          </button>
          <span className="mx-1">/</span>
          <button
            onClick={() => goToScene('oasArchives')}
            className="hover:text-[#1e5b9d]"
          >
            档案管理
          </button>
          <span className="mx-1">/</span>
          <span className="text-gray-700">{archive.name} 档案详情</span>
        </div>

        <motion.div
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.3 }}
          className="space-y-4"
        >
          {/* 档案头部 */}
          <div className="bg-white border border-gray-200 p-5">
            <div className="flex items-start gap-4">
              <div className={`w-14 h-14 ${iconBg} flex items-center justify-center flex-shrink-0`}>
                <Icon className={`w-6 h-6 ${iconColor}`} />
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 flex-wrap">
                  <h1 className="text-lg font-medium text-gray-800">
                    {archive.name}
                  </h1>
                  <span className="text-xs bg-red-500 text-white px-2 py-0.5">
                    {archive.status}
                  </span>
                  <span className="text-xs text-gray-400 font-mono">
                    {archive.archiveNo}
                  </span>
                </div>
                <div className="mt-2 grid grid-cols-2 md:grid-cols-4 gap-3 text-sm">
                  <div className="flex items-center gap-2 text-gray-600">
                    <User className="w-4 h-4 text-gray-400" />
                    <span>{archive.age} 岁</span>
                  </div>
                  <div className="flex items-center gap-2 text-gray-600">
                    <MapPin className="w-4 h-4 text-gray-400" />
                    <span>{archive.city}</span>
                  </div>
                  <div className="flex items-center gap-2 text-gray-600">
                    <Archive className="w-4 h-4 text-gray-400" />
                    <span>{archive.organType}</span>
                  </div>
                  <div className="flex items-center gap-2 text-gray-600">
                    <Calendar className="w-4 h-4 text-gray-400" />
                    <span>手术：{archive.transplantDate}</span>
                  </div>
                </div>
                <p className="mt-3 text-sm text-gray-600 leading-relaxed">
                  {archive.description}
                </p>
              </div>
            </div>
          </div>

          {/* 随访记录 */}
          <div className="bg-white border border-gray-200">
            <div className="border-b border-gray-200 px-5 py-3 flex items-center gap-2">
              <FileText className="w-4 h-4 text-[#1e5b9d]" />
              <h2 className="text-sm font-medium text-gray-800">
                随访记录
                <span className="text-xs text-gray-500 ml-2">
                  共 {archive.followUpRecords.length} 条
                </span>
              </h2>
            </div>

            <div className="divide-y divide-gray-100">
              {archive.followUpRecords.map((record, i) => (
                <motion.div
                  key={i}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ delay: i * 0.08 }}
                  className="p-5"
                >
                  <div className="flex items-start gap-4">
                    <div className="flex flex-col items-center">
                      <div className="w-3 h-3 rounded-full bg-[#1e5b9d]" />
                      {i < archive.followUpRecords.length - 1 && (
                        <div className="w-px flex-1 bg-gray-200 my-2" style={{ minHeight: 40 }} />
                      )}
                    </div>
                    <div className="flex-1 min-w-0 pb-2">
                      <div className="flex items-center gap-3 flex-wrap">
                        <h3 className="text-sm font-medium text-gray-800">
                          {record.type}
                        </h3>
                        <span className="text-xs text-gray-500 flex items-center gap-1">
                          <Calendar className="w-3 h-3" />
                          {record.date}
                        </span>
                        <span className="text-xs text-gray-400 ml-auto">
                          记录人：{record.doctor}
                        </span>
                      </div>
                      <p className="mt-2 text-sm text-gray-600 leading-relaxed whitespace-pre-line">
                        {record.content}
                      </p>
                    </div>
                  </div>
                </motion.div>
              ))}
            </div>
          </div>

          {/* 操作提示 */}
          <div className="bg-amber-50 border border-amber-200 rounded p-4">
            <div className="flex items-start gap-3">
              <Heart className="w-5 h-5 text-amber-600 flex-shrink-0 mt-0.5" />
              <div className="text-xs text-amber-800 space-y-1">
                <p className="font-medium">器官协调员提示</p>
                <p>
                  该档案标记为「{archive.status}」，需重点跟进。请密切关注患者术后恢复情况，定期随访并记录异常事件。
                </p>
                <p>
                  如发现任何异常情况，请立即上报上级主管部门，并同步至对应合作医院。
                </p>
              </div>
            </div>
          </div>
        </motion.div>
      </div>
    </div>
  );
}
