import { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Send, ArrowLeft } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';

export interface ChatMessage {
  id: string;
  sender: 'me' | 'shenchi' | 'shenbo';
  senderName: string;
  content: string;
  time: string;
}

export type ChatViewerPerspective = 'chengwei' | 'shenchi' | 'shenbo';

interface ChatPanelProps {
  contactName: string;
  contactInitial: string;
  initialMessages: ChatMessage[];
  onClose: () => void;
  onBack?: () => void;
  showBack?: boolean;
  onSend?: (text: string) => void;
  variant?: 'light' | 'dark';
  accentColor?: 'rose' | 'blue' | 'slate' | 'amber';
  viewerPerspective?: ChatViewerPerspective;
}

const colorMap = {
  rose: {
    self: 'bg-rose-500 text-white',
    other: 'bg-rose-900/40 text-rose-200 border-rose-800/30',
    bg: 'from-rose-950/20 to-black',
    header: 'bg-rose-950/50 border-rose-900/30',
    input: 'bg-rose-950/30 border-rose-900/30 text-rose-200',
    placeholder: 'placeholder-rose-800',
  },
  blue: {
    self: 'bg-blue-500 text-white',
    other: 'bg-blue-900/40 text-blue-200 border-blue-800/30',
    bg: 'from-blue-950/20 to-black',
    header: 'bg-blue-950/50 border-blue-900/30',
    input: 'bg-blue-950/30 border-blue-900/30 text-blue-200',
    placeholder: 'placeholder-blue-800',
  },
  slate: {
    self: 'bg-slate-700 text-white',
    other: 'bg-white text-slate-700 border-slate-200',
    bg: 'from-slate-50 to-white',
    header: 'bg-white border-slate-200',
    input: 'bg-white border-slate-200 text-slate-700',
    placeholder: 'placeholder-slate-400',
  },
  amber: {
    self: 'bg-amber-500 text-white',
    other: 'bg-zinc-900/70 text-zinc-300 border-zinc-700/50',
    bg: 'from-amber-950/20 to-black',
    header: 'bg-amber-950/50 border-amber-900/30',
    input: 'bg-amber-950/30 border-amber-900/30 text-amber-200',
    placeholder: 'placeholder-amber-800',
  },
};

export default function ChatPanel({
  contactName,
  contactInitial,
  initialMessages,
  onClose,
  onBack,
  showBack = false,
  onSend,
  variant = 'light',
  accentColor = 'slate',
  viewerPerspective = 'chengwei',
}: ChatPanelProps) {
  const [messages, setMessages] = useState<ChatMessage[]>(initialMessages);
  const [input, setInput] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);
  const colors = colorMap[accentColor];

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages.length]);

  const handleSend = () => {
    if (!input.trim()) return;
    const senderKey: ChatMessage['sender'] =
      viewerPerspective === 'shenchi'
        ? 'shenchi'
        : viewerPerspective === 'shenbo'
          ? 'shenbo'
          : 'me';
    const newMsg: ChatMessage = {
      id: `m-${Date.now()}`,
      sender: senderKey,
      senderName: '我',
      content: input.trim(),
      time: '刚刚',
    };
    setMessages((prev) => [...prev, newMsg]);
    setInput('');
    onSend?.(input.trim());
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const textColor = variant === 'dark' ? 'text-white' : 'text-slate-800';
  const subColor = variant === 'dark' ? 'text-white/60' : 'text-slate-500';

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: 10 }}
      className={`bg-gradient-to-b ${colors.bg} border ${variant === 'dark' ? 'border-white/10' : 'border-slate-200'} rounded-lg overflow-hidden flex flex-col h-[500px] max-h-[70vh]`}
    >
      {/* 头部 */}
      <div className={`px-4 py-3 border-b ${colors.header} flex items-center gap-3`}>
        {showBack && onBack && (
          <Button
            variant="ghost"
            size="icon"
            className="h-8 w-8"
            onClick={onBack}
          >
            <ArrowLeft className={`w-4 h-4 ${subColor}`} />
          </Button>
        )}
        <div className="w-9 h-9 rounded-full bg-slate-200 flex items-center justify-center flex-shrink-0">
          <span className="text-sm font-medium text-slate-600">{contactInitial}</span>
        </div>
        <div className="flex-1 min-w-0">
          <div className={`text-sm font-medium ${textColor}`}>{contactName}</div>
          <div className={`text-xs ${subColor}`}>在线</div>
        </div>
        <Button
          variant="ghost"
          size="icon"
          className="h-8 w-8"
          onClick={onClose}
        >
          <X className={`w-4 h-4 ${subColor}`} />
        </Button>
      </div>

      {/* 消息区 */}
      <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-3">
        {messages.map((msg) => {
          const isSelf = msg.sender === 'me' || msg.sender === viewerPerspective;
          // 角色视角下，对方（程未）的气泡用深灰色
          const isRolePerspective = viewerPerspective !== 'chengwei';
          const otherBubbleClass = isRolePerspective
            ? 'bg-zinc-800/80 text-zinc-300 border-zinc-700/50'
            : `${colors.other} border`;
          return (
            <motion.div
              key={msg.id}
              initial={{ opacity: 0, y: 8 }}
              animate={{ opacity: 1, y: 0 }}
              className={`flex ${isSelf ? 'justify-end' : 'justify-start'}`}
            >
              <div className={`max-w-[75%] ${isSelf ? 'items-end' : 'items-start'} flex flex-col gap-1`}>
                <div
                  className={`px-3.5 py-2.5 rounded-2xl text-sm leading-relaxed ${
                    isSelf
                      ? `${colors.self} rounded-br-sm`
                      : `${otherBubbleClass} rounded-bl-sm`
                  }`}
                >
                  {msg.content.split('\n').map((line, i) => (
                    <p key={i}>{line}</p>
                  ))}
                </div>
                <span className={`text-[10px] ${subColor} ${isSelf ? 'text-right' : 'text-left'}`}>
                  {msg.time}
                </span>
              </div>
            </motion.div>
          );
        })}
      </div>

      {/* 输入区 */}
      <div className={`p-3 border-t ${variant === 'dark' ? 'border-white/10' : 'border-slate-200'}`}>
        <div className="flex items-center gap-2">
          <Input
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="输入消息..."
            className={`${colors.input} ${colors.placeholder} text-sm h-10`}
          />
          <Button size="icon" onClick={handleSend} disabled={!input.trim()}>
            <Send className="w-4 h-4" />
          </Button>
        </div>
      </div>
    </motion.div>
  );
}
