import { useState } from 'react';
import { useGame } from '../GameContext';
import { motion } from 'framer-motion';
import { MOCK_STORY } from '@/data/story';
import {
  Search,
  Filter,
  Calendar,
  Clock,
  AlertCircle,
  CheckCircle2,
  ChevronRight,
} from 'lucide-react';
import { Input } from '@/components/ui/input';
import SceneChrome from '../components/SceneChrome';
import OasTopNav from '../components/OasTopNav';

const priorityColors: Record<string, string> = {
  high: 'bg-red-100 text-red-700',
  medium: 'bg-amber-100 text-amber-700',
  low: 'bg-green-100 text-green-700',
};

const priorityLabels: Record<string, string> = {
  high: '高',
  medium: '中',
  low: '低',
};

export default function OasFollowupScene() {
  const { goToScene } = useGame();
  const { oas } = MOCK_STORY;
  const [keyword, setKeyword] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');

  const filtered = oas.followUpTasks.filter((t) => {
    const matchKw =
      !keyword ||
      t.name.includes(keyword) ||
      t.archiveNo.includes(keyword) ||
      t.organType.includes(keyword);
    const matchStatus = statusFilter === 'all' || t.status === statusFilter;
    return matchKw && matchStatus;
  });

  const stats = [
    { label: '本月完成随访', value: '356', icon: CheckCircle2, color: 'text-green-600' },
    { label: '待跟进', value: '47', icon: Clock, color: 'text-amber-600' },
    { label: '高优先级', value: '12', icon: AlertCircle, color: 'text-red-600' },
    { label: '术后随访中', value: '892', icon: Calendar, color: 'text-[#1e5b9d]' },
  ];

  return (
    <div className="min-h-screen bg-[#f0f2f5]">
      <SceneChrome variant="system" />
      <OasTopNav activeTab="followup" />

      <div className="max-w-6xl mx-auto px-4 py-5">
        {/* 面包屑 */}
        <div className="text-xs text-gray-500 mb-4">
          <button
            onClick={() => goToScene('oasDashboard')}
            className="hover:text-[#1e5b9d]"
          >
            工作台
          </button>
          <span className="mx-1">/</span>
          <span className="text-gray-700">随访管理</span>
        </div>

        <motion.div
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.3 }}
          className="space-y-4"
        >
          {/* 统计卡片 */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            {stats.map((stat, i) => {
              const Icon = stat.icon;
              return (
                <div key={i} className="bg-white border border-gray-200 p-4">
                  <div className="flex items-center gap-3">
                    <div className="w-9 h-9 bg-gray-50 flex items-center justify-center">
                      <Icon className={`w-4 h-4 ${stat.color}`} />
                    </div>
                    <div>
                      <p className="text-xs text-gray-500">{stat.label}</p>
                      <p className="text-xl font-bold text-gray-800 tabular-nums">
                        {stat.value}
                      </p>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>

          {/* 搜索筛选 */}
          <div className="bg-white border border-gray-200 p-4">
            <div className="flex flex-wrap items-center gap-3">
              <div className="relative flex-1 min-w-[200px]">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                <Input
                  type="search"
                  value={keyword}
                  onChange={(e) => setKeyword(e.target.value)}
                  placeholder="搜索姓名 / 档案编号 / 器官类型"
                  className="pl-9 h-9 text-sm"
                />
              </div>
              <div className="flex items-center gap-2">
                <Filter className="w-4 h-4 text-gray-500" />
                <select
                  value={statusFilter}
                  onChange={(e) => setStatusFilter(e.target.value)}
                  className="h-9 px-3 text-sm border border-gray-300 rounded bg-white text-gray-700 focus:outline-none focus:border-[#1e5b9d]"
                >
                  <option value="all">全部状态</option>
                  <option value="待随访">待随访</option>
                  <option value="进行中">进行中</option>
                  <option value="已完成">已完成</option>
                </select>
              </div>
            </div>
          </div>

          {/* 随访任务列表 */}
          <div className="bg-white border border-gray-200">
            <div className="border-b border-gray-200 px-4 py-3">
              <h2 className="text-sm font-medium text-gray-800">
                随访任务
                <span className="text-xs text-gray-500 ml-2">
                  共 {filtered.length} 条待处理
                </span>
              </h2>
            </div>

            <div className="divide-y divide-gray-100">
              {filtered.map((task, i) => (
                <motion.div
                  key={task.id}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ delay: i * 0.03 }}
                  className="p-4 hover:bg-blue-50/30 cursor-pointer transition-colors"
                  onClick={() => {
                    if (task.name === '沈迟') goToScene('shenchiPuzzle');
                  }}
                >
                  <div className="flex items-center justify-between gap-3">
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 flex-wrap">
                        <h3 className="text-sm font-medium text-gray-800">
                          {task.name}
                        </h3>
                        <span className="text-xs text-gray-400 font-mono">
                          {task.archiveNo}
                        </span>
                        <span
                          className={`text-xs px-1.5 py-0.5 ${
                            priorityColors[task.priority] || priorityColors.low
                          }`}
                        >
                          优先级：{priorityLabels[task.priority] || task.priority}
                        </span>
                      </div>
                      <div className="text-xs text-gray-500 mt-1 flex items-center gap-2 flex-wrap">
                        <span>{task.organType}</span>
                        <span className="text-gray-300">|</span>
                        <span className="flex items-center gap-1">
                          <Calendar className="w-3 h-3" />
                          随访日期：{task.dueDate}
                        </span>
                        <span className="text-gray-300">|</span>
                        <span
                          className={
                            task.status === '待随访'
                              ? 'text-amber-600'
                              : task.status === '已完成'
                                ? 'text-green-600'
                                : 'text-blue-600'
                          }
                        >
                          {task.status}
                        </span>
                      </div>
                    </div>
                    <div className="flex items-center gap-1 text-xs text-[#1e5b9d] flex-shrink-0">
                      开始随访
                      <ChevronRight className="w-3 h-3" />
                    </div>
                  </div>
                </motion.div>
              ))}
            </div>

            {filtered.length === 0 && (
              <div className="p-12 text-center text-gray-400 text-sm">
                暂无随访任务
              </div>
            )}
          </div>
        </motion.div>
      </div>
    </div>
  );
}
