import { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useGame } from '../GameContext';

// 打破第四面墙的片尾
// 所有结局走完剧情后，统一播放这段直接对玩家说话的内容
export default function FourthWallEnding() {
  const { resetGame } = useGame();

  // 阶段：black → line1 → line2 → heartbeat → redText → bottomLine → button
  const [phase, setPhase] = useState<'black' | 'line1' | 'line2' | 'heartbeat' | 'redText' | 'bottomLine' | 'button'>('black');
  const audioCtxRef = useRef<AudioContext | null>(null);
  const beatIntervalRef = useRef<number | null>(null);

  // 阶段推进时间轴
  useEffect(() => {
    const timers: ReturnType<typeof setTimeout>[] = [];

    // 黑屏 3 秒后出第一行
    timers.push(setTimeout(() => setPhase('line1'), 3000));
    // 第一行停留 2 秒后出第二行
    timers.push(setTimeout(() => setPhase('line2'), 5000));
    // 第二行停留 3 秒后心跳开始
    timers.push(setTimeout(() => setPhase('heartbeat'), 8000));
    // 心跳 2 秒后出红字
    timers.push(setTimeout(() => setPhase('redText'), 10000));
    // 红字 3 秒后出底部小字
    timers.push(setTimeout(() => setPhase('bottomLine'), 13000));
    // 底部字 5 秒后出退出按钮
    timers.push(setTimeout(() => setPhase('button'), 18000));

    return () => timers.forEach(clearTimeout);
  }, []);

  // 心跳声 + 渐强
  useEffect(() => {
    if (phase !== 'heartbeat' && phase !== 'redText' && phase !== 'bottomLine' && phase !== 'button') return;

    let gainValue = 0.08; // 初始音量
    const maxGain = 0.4;

    const playBeat = () => {
      try {
        if (!audioCtxRef.current) {
          const AC = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
          audioCtxRef.current = new AC();
        }
        const ctx = audioCtxRef.current;
        const now = ctx.currentTime;

        // 第一声（lub）
        const osc1 = ctx.createOscillator();
        const gain1 = ctx.createGain();
        osc1.type = 'sine';
        osc1.frequency.setValueAtTime(70, now);
        osc1.frequency.exponentialRampToValueAtTime(50, now + 0.1);
        gain1.gain.setValueAtTime(gainValue, now);
        gain1.gain.exponentialRampToValueAtTime(0.001, now + 0.15);
        osc1.connect(gain1).connect(ctx.destination);
        osc1.start(now);
        osc1.stop(now + 0.15);

        // 第二声（dub），延迟 180ms
        const osc2 = ctx.createOscillator();
        const gain2 = ctx.createGain();
        osc2.type = 'sine';
        osc2.frequency.setValueAtTime(65, now + 0.18);
        osc2.frequency.exponentialRampToValueAtTime(45, now + 0.28);
        gain2.gain.setValueAtTime(gainValue * 0.8, now + 0.18);
        gain2.gain.exponentialRampToValueAtTime(0.001, now + 0.33);
        osc2.connect(gain2).connect(ctx.destination);
        osc2.start(now + 0.18);
        osc2.stop(now + 0.33);

        // 每跳稍微渐强一点
        if (gainValue < maxGain) {
          gainValue = Math.min(maxGain, gainValue + 0.01);
        }
      } catch {
        // 忽略音频错误
      }
    };

    // 立即打第一声
    playBeat();

    // 双跳节奏：1200ms 一个周期
    beatIntervalRef.current = window.setInterval(playBeat, 1200);

    return () => {
      if (beatIntervalRef.current) {
        clearInterval(beatIntervalRef.current);
        beatIntervalRef.current = null;
      }
    };
  }, [phase === 'heartbeat' || phase === 'redText' || phase === 'bottomLine' || phase === 'button' ? 'active' : 'idle']);

  const isHeartbeatPhase = phase === 'heartbeat' || phase === 'redText' || phase === 'bottomLine' || phase === 'button';

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.8 }}
      className="fixed inset-0 bg-black z-[9999] flex flex-col items-center justify-center"
    >
      {/* 心跳呼吸缩放效果 */}
      <motion.div
        className="w-full h-full flex flex-col items-center justify-center px-6"
        animate={isHeartbeatPhase ? { scale: [1, 1.015, 1] } : { scale: 1 }}
        transition={
          isHeartbeatPhase
            ? { duration: 1.2, repeat: Infinity, ease: 'easeInOut' }
            : { duration: 0 }
        }
      >
        <div className="max-w-md w-full space-y-6 text-center">
          {/* 第一行：故事讲完了 */}
          <AnimatePresence>
            {(phase === 'line1' || phase === 'line2' || isHeartbeatPhase) && (
              <motion.p
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0 }}
                transition={{ duration: 2 }}
                className="text-stone-400 text-sm leading-relaxed"
              >
                好了。故事讲完了。
              </motion.p>
            )}
          </AnimatePresence>

          {/* 第二行：把手放胸口 */}
          <AnimatePresence>
            {(phase === 'line2' || isHeartbeatPhase) && (
              <motion.p
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0 }}
                transition={{ duration: 2 }}
                className="text-stone-400 text-sm leading-relaxed"
              >
                现在，把手机/电脑放下来。
                <br />
                把手放在自己胸口。
              </motion.p>
            )}
          </AnimatePresence>

          {/* 红字：七十四下 */}
          <AnimatePresence>
            {(phase === 'redText' || phase === 'bottomLine' || phase === 'button') && (
              <motion.div
                initial={{ opacity: 0, y: 15 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0 }}
                transition={{ duration: 2.5 }}
                className="space-y-3 pt-4"
              >
                <p className="text-red-500/80 text-base leading-loose">
                  数一下。
                </p>
                <p className="text-red-500/80 text-base leading-loose">
                  如果你的心跳也是七十四下——
                </p>
                <p className="text-red-500/80 text-base leading-loose">
                  那也没关系。
                </p>
                <p className="text-red-500/60 text-sm leading-loose italic">
                  它只是借你，再睡一会儿。
                </p>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </motion.div>

      {/* 底部小字 */}
      <AnimatePresence>
        {(phase === 'bottomLine' || phase === 'button') && (
          <motion.p
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 2 }}
            className="fixed bottom-16 text-stone-700 text-[11px]"
          >
            你不会告诉别人的，对吗？
          </motion.p>
        )}
      </AnimatePresence>

      {/* 退出按钮 */}
      <AnimatePresence>
        {phase === 'button' && (
          <motion.button
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 1.5 }}
            onClick={resetGame}
            className="fixed bottom-6 text-stone-600 text-xs hover:text-stone-400 transition-colors"
          >
            退出
          </motion.button>
        )}
      </AnimatePresence>
    </motion.div>
  );
}
